func NewWebhookHandler(secret []byte, nowFn func() time.Time, sink EventSink) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		tsHeader := strings.TrimSpace(r.Header.Get("X-Webhook-Timestamp"))
		sigHeader := strings.TrimSpace(r.Header.Get("X-Webhook-Signature-256"))
		if tsHeader == "" || !strings.HasPrefix(sigHeader, "sha256=") {
			http.Error(w, "missing authentication headers", http.StatusUnauthorized)
			return
		}

		tsUnix, err := strconv.ParseInt(tsHeader, 10, 64)
		if err != nil {
			http.Error(w, "invalid timestamp", http.StatusBadRequest)
			return
		}
		delta := nowFn().Sub(time.Unix(tsUnix, 0))
		if delta < -maxSkew || delta > maxSkew {
			http.Error(w, "stale webhook timestamp", http.StatusUnauthorized)
			return
		}

		gotMAC, err := hex.DecodeString(strings.TrimPrefix(sigHeader, "sha256="))
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "malformed signature", http.StatusUnauthorized)
			return
		}

		r.Body = http.MaxBytesReader(w, r.Body, maxWebhookBytes)
		body, err := io.ReadAll(r.Body)
		if err != nil {
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
				return
			}
			http.Error(w, "failed reading body", http.StatusBadRequest)
			return
		}

		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(tsHeader))
		mac.Write([]byte("."))
		mac.Write(body)
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "signature mismatch", http.StatusUnauthorized)
			return
		}

		if err := sink(r, body); err != nil {
			http.Error(w, "sink failure", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusAccepted)
	}
}
