def _nil(val: str) -> str | None:
    return None if val == "-" else val


def _parse_sd_elements(buf: str, pos: int) -> tuple[dict[str, dict[str, str]], int]:
    if pos >= len(buf):
        raise SyslogParseError("missing structured-data section")
    if buf[pos] == "-":
        return {}, pos + 1
    if buf[pos] != "[":
        raise SyslogParseError("expected '[' or '-' for structured-data")

    sd: dict[str, dict[str, str]] = {}
    n = len(buf)
    while pos < n and buf[pos] == "[":
        pos += 1
        id_start = pos
        while pos < n and buf[pos] not in (" ", "]", "=", '"'):
            pos += 1
        sd_id = buf[id_start:pos]
        if not sd_id:
            raise SyslogParseError("empty sd-id")
        params = sd.setdefault(sd_id, {})

        while pos < n and buf[pos] == " ":
            pos += 1
            k_start = pos
            while pos < n and buf[pos] not in ("=", " ", "]", '"'):
                pos += 1
            key = buf[k_start:pos]
            if not key or pos >= n or buf[pos] != "=" or pos + 1 >= n or buf[pos + 1] != '"':
                raise SyslogParseError(f"malformed sd-param in {sd_id}")
            pos += 2  # skip ="
            val_chars: list[str] = []
            closed_quote = False
            while pos < n:
                ch = buf[pos]
                if ch == "\\":
                    pos += 1
                    if pos >= n:
                        raise SyslogParseError("unterminated escape in sd-param")
                    val_chars.append(buf[pos])
                    pos += 1
                elif ch == '"':
                    closed_quote = True
                    pos += 1
                    break
                else:
                    val_chars.append(ch)
                    pos += 1
            if not closed_quote:
                raise SyslogParseError("unterminated quote in sd-param")
            params[key] = "".join(val_chars)

        if pos >= n or buf[pos] != "]":
            raise SyslogParseError("unclosed structured-data element")
        pos += 1

    return sd, pos


def parse_rfc5424_line(line: str) -> Syslog5424Record:
    raw = line.rstrip("\r\n")
    m = _HEADER_RE.match(raw)
    if not m:
        raise SyslogParseError("invalid RFC 5424 header")

    pri = int(m.group("pri"))
    if pri > 191:
        raise SyslogParseError(f"priority out of range: {pri}")

    sd, next_pos = _parse_sd_elements(raw, m.end())
    msg = ""
    if next_pos < len(raw):
        if raw[next_pos] != " ":
            raise SyslogParseError("expected space delimiter before MSG")
        msg = raw[next_pos + 1 :]
        if msg.startswith("\ufeff"):
            msg = msg[1:]

    return Syslog5424Record(
        facility=pri >> 3,
        severity=pri & 0x07,
        version=int(m.group("ver")),
        timestamp=_nil(m.group("ts")),
        hostname=_nil(m.group("host")),
        app_name=_nil(m.group("app")),
        proc_id=_nil(m.group("proc")),
        msg_id=_nil(m.group("msgid")),
        structured_data=sd,
        message=msg,
    )
