export function requireOrgScopes(requiredScopes: readonly string[]): MiddlewareHandler<AppEnv> {
  return async (c, next) => {
    const claims = c.get("jwtPayload");
    const nowSec = Math.floor(Date.now() / 1000);

    if (!claims || !claims.sub || !claims.org_id || typeof claims.exp !== "number" || claims.exp <= nowSec) {
      return c.json(
        {
          type: "urn:auth:unauthorized",
          title: "Unauthorized",
          status: 401,
          detail: "Missing or expired bearer token claims.",
        },
        401,
        { "Content-Type": "application/problem+json" },
      );
    }

    const routeOrgId = c.req.param("orgId");
    if (!routeOrgId || routeOrgId !== claims.org_id) {
      return c.json(
        {
          type: "urn:auth:tenant-mismatch",
          title: "Forbidden",
          status: 403,
          detail: "Token organization does not match requested resource tenant.",
        },
        403,
        { "Content-Type": "application/problem+json" },
      );
    }

    const granted = new Set(
      (claims.scope ?? "")
        .split(/\s+/)
        .map((s) => s.trim())
        .filter((s) => s.length > 0),
    );
    const missing = requiredScopes.filter((scope) => !granted.has(scope));

    if (missing.length > 0) {
      return c.json(
        {
          type: "urn:auth:insufficient-scope",
          title: "Insufficient Scope",
          status: 403,
          detail: `Missing required scope(s): ${missing.join(", ")}`,
          missing,
        },
        403,
        { "Content-Type": "application/problem+json" },
      );
    }

    await next();
  };
}
