[[nodiscard]] bool ring_read(byte_ring_t *r, uint8_t *dst, size_t req_len, size_t *out_read) {
    if (r == nullptr || r->buf == nullptr || out_read == nullptr) {
        return false;
    }
    *out_read = 0;
    if (r->cap == 0 || (r->cap & (r->cap - 1u)) != 0) {
        return false;
    }

    size_t avail = 0;
    if (ckd_sub(&avail, r->write_pos, r->read_pos) || avail > r->cap) {
        return false;
    }
    if (req_len == 0 || avail == 0) {
        return req_len == 0 || dst != nullptr;
    }
    if (dst == nullptr) {
        return false;
    }

    size_t to_copy = req_len < avail ? req_len : avail;
    size_t mask = r->cap - 1u;
    size_t start_idx = r->read_pos & mask;
    size_t first_chunk = r->cap - start_idx;
    if (first_chunk > to_copy) {
        first_chunk = to_copy;
    }

    memcpy(dst, r->buf + start_idx, first_chunk);
    size_t second_chunk = to_copy - first_chunk;
    if (second_chunk > 0) {
        memcpy(dst + first_chunk, r->buf, second_chunk);
    }

    size_t next_read = 0;
    if (ckd_add(&next_read, r->read_pos, to_copy)) {
        return false;
    }
    r->read_pos = next_read;
    *out_read = to_copy;
    return true;
}
