fn encode_aad(ctx: &EnvelopeContext<'_>) -> Vec<u8> {
    let tenant_bytes = ctx.tenant_id.as_bytes();
    let key_id_bytes = ctx.key_id.as_bytes();
    let mut aad = Vec::with_capacity(10 + 2 + 4 + tenant_bytes.len() + 4 + key_id_bytes.len());
    aad.extend_from_slice(b"env-v1\x00");
    aad.extend_from_slice(&ctx.schema_ver.to_be_bytes());
    aad.extend_from_slice(&(tenant_bytes.len() as u32).to_be_bytes());
    aad.extend_from_slice(tenant_bytes);
    aad.extend_from_slice(&(key_id_bytes.len() as u32).to_be_bytes());
    aad.extend_from_slice(key_id_bytes);
    aad
}

pub fn seal_record(
    key: &[u8; 32],
    ctx: &EnvelopeContext<'_>,
    plaintext: &[u8],
) -> Result<Vec<u8>, EnvelopeError> {
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| EnvelopeError::AeadFailure)?;
    let nonce = Aes256Gcm::generate_nonce(&mut OsRng);
    let aad = encode_aad(ctx);
    let ct = cipher
        .encrypt(&nonce, Payload { msg: plaintext, aad: &aad })
        .map_err(|_| EnvelopeError::AeadFailure)?;
    let mut out = Vec::with_capacity(NONCE_LEN + ct.len());
    out.extend_from_slice(nonce.as_slice());
    out.extend_from_slice(&ct);
    Ok(out)
}

pub fn open_record(
    key: &[u8; 32],
    ctx: &EnvelopeContext<'_>,
    sealed: &[u8],
) -> Result<Vec<u8>, EnvelopeError> {
    if sealed.len() < NONCE_LEN + 16 {
        return Err(EnvelopeError::InvalidCiphertextLength);
    }
    let (nonce_bytes, ct) = sealed.split_at(NONCE_LEN);
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| EnvelopeError::AeadFailure)?;
    let nonce = Nonce::from_slice(nonce_bytes);
    let aad = encode_aad(ctx);
    cipher
        .decrypt(nonce, Payload { msg: ct, aad: &aad })
        .map_err(|_| EnvelopeError::AeadFailure)
}
