        .checked_add(total_len as usize)
        .ok_or(EpbError::TruncatedBuffer)?;
    let block = buf.get(offset..block_end).ok_or(EpbError::TruncatedBuffer)?;

    let tail_slice = &block[block.len() - 4..];
    let tail_len = u32::from_le_bytes([tail_slice[0], tail_slice[1], tail_slice[2], tail_slice[3]]);
    if tail_len != total_len {
