export function createSlidingWindowLimiter(opts: SlidingLimiterOptions): RequestHandler {
  const buckets = new Map<string, number[]>();
  const keyOf = opts.keyFn ?? ((req: Request) => req.ip || "unknown");
  const nowOf = opts.nowFn ?? (() => Date.now());

  return (req: Request, res: Response, next: NextFunction): void => {
    const now = nowOf();
    const cutoff = now - opts.windowMs;
    const key = keyOf(req);
    const existing = buckets.get(key) ?? [];

    let firstValidIdx = 0;
    while (firstValidIdx < existing.length && existing[firstValidIdx] <= cutoff) {
      firstValidIdx++;
    }
    const active = firstValidIdx > 0 ? existing.slice(firstValidIdx) : existing;

    res.setHeader("RateLimit-Limit", String(opts.maxRequests));

    if (active.length >= opts.maxRequests) {
      buckets.set(key, active);
      const oldestHit = active[0];
      const retryAfterSec = Math.max(1, Math.ceil((oldestHit + opts.windowMs - now) / 1000));
      res.setHeader("RateLimit-Remaining", "0");
      res.setHeader("RateLimit-Reset", String(retryAfterSec));
      res.setHeader("Retry-After", String(retryAfterSec));
      res.status(429).json({ error: "rate_limit_exceeded", retry_after_seconds: retryAfterSec });
      return;
    }

    active.push(now);
    buckets.set(key, active);
    const remaining = Math.max(0, opts.maxRequests - active.length);
    const resetSec = Math.max(1, Math.ceil((active[0] + opts.windowMs - now) / 1000));
    res.setHeader("RateLimit-Remaining", String(remaining));
    res.setHeader("RateLimit-Reset", String(resetSec));
    next();
  };
}
