func ServeSignedArtifact(rootDir string, signingKey []byte, nowFn func() time.Time) http.HandlerFunc {
	cleanRoot := filepath.Clean(rootDir)
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		q := r.URL.Query()
		rawFile := q.Get("file")
		expStr := q.Get("exp")
		sigHex := q.Get("sig")
		if rawFile == "" || expStr == "" || sigHex == "" || strings.Contains(rawFile, "\\") || strings.ContainsRune(rawFile, 0) {
			http.Error(w, "invalid signed parameters", http.StatusBadRequest)
			return
		}

		cleaned := strings.TrimPrefix(path.Clean("/"+rawFile), "/")
		if cleaned == "" || cleaned == "." || cleaned != rawFile {
			http.Error(w, "non-canonical artifact path", http.StatusBadRequest)
			return
		}

		expUnix, err := strconv.ParseInt(expStr, 10, 64)
		if err != nil || nowFn().Unix() > expUnix {
			http.Error(w, "link expired or invalid", http.StatusForbidden)
			return
		}

		gotSig, err := hex.DecodeString(sigHex)
		if err != nil || len(gotSig) != sha256.Size {
			http.Error(w, "invalid signature", http.StatusForbidden)
			return
		}

		mac := hmac.New(sha256.New, signingKey)
		mac.Write([]byte(r.Method + "\n" + cleaned + "\n" + expStr))
		if !hmac.Equal(gotSig, mac.Sum(nil)) {
			http.Error(w, "signature mismatch", http.StatusForbidden)
			return
		}

		diskPath := filepath.Join(cleanRoot, filepath.FromSlash(cleaned))
		if !strings.HasPrefix(diskPath, cleanRoot+string(filepath.Separator)) {
			http.Error(w, "forbidden path", http.StatusForbidden)
			return
		}

		f, err := os.Open(diskPath)
		if err != nil {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
		defer f.Close()

		st, err := f.Stat()
		if err != nil || !st.Mode().IsRegular() {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}

		w.Header().Set("X-Content-Type-Options", "nosniff")
		http.ServeContent(w, r, st.Name(), st.ModTime(), f)
	}
}
