const HEX64_RE = /^sha256=([0-9a-fA-F]{64})$/;

export function createHubSignaturePreHandler(webhookSecret: string): preHandlerHookHandler {
  if (!webhookSecret || webhookSecret.length < 16) {
    throw new Error("webhookSecret must be at least 16 chars");
  }
  const secretBuf = Buffer.from(webhookSecret, "utf8");

  return async (req: FastifyRequest, reply: FastifyReply) => {
    if (!Buffer.isBuffer(req.rawBody)) {
      return reply.code(400).send({ error: "missing_raw_body" });
    }

    const rawHeader = req.headers["x-hub-signature-256"];
    if (typeof rawHeader !== "string") {
      return reply.code(401).send({ error: "missing_signature_header" });
    }

    const match = HEX64_RE.exec(rawHeader.trim());
    if (!match) {
      return reply.code(401).send({ error: "malformed_signature_header" });
    }

    const providedSig = Buffer.from(match[1], "hex");
    const expectedSig = createHmac("sha256", secretBuf).update(req.rawBody).digest();

    if (providedSig.length !== expectedSig.length || !timingSafeEqual(providedSig, expectedSig)) {
      return reply.code(401).send({ error: "invalid_signature" });
    }
  };
}
```

