pub fn decode_uleb128_u64(input: &[u8]) -> Result<(u64, &[u8]), Leb128Error> {
    let mut result = 0u64;
    for idx in 0..10usize {
        let &byte = input.get(idx).ok_or(Leb128Error::UnexpectedEof)?;
        if idx == 9 && byte > 0x01 {
            return Err(Leb128Error::Overflow);
