        let shift = (idx as u32) * 7;
        result |= ((byte & 0x7f) as u64) << shift;
        if (byte & 0x80) == 0 {
            let rest = input.get(idx + 1..).unwrap_or(&[]);
            return Ok((result, rest));
        }
    }
    Err(Leb128Error::Overflow)
}
