def parse_rdata(rtype: int, packet: bytes, rdata_offset: int, rdlength: int) -> str | list[bytes]:
    if rdata_offset < 0 or rdlength < 0 or rdata_offset + rdlength > len(packet):
        raise DnsRdataError("RDATA slice out of packet bounds")

    rdata = memoryview(packet)[rdata_offset : rdata_offset + rdlength]

    if rtype == TYPE_A:
        if len(rdata) != 4:
            raise DnsRdataError(f"A record requires 4 bytes, got {len(rdata)}")
        return str(ipaddress.IPv4Address(bytes(rdata)))

    if rtype == TYPE_AAAA:
        if len(rdata) != 16:
            raise DnsRdataError(f"AAAA record requires 16 bytes, got {len(rdata)}")
        return str(ipaddress.IPv6Address(bytes(rdata)))

    if rtype == TYPE_TXT:
        if len(rdata) == 0:
            raise DnsRdataError("TXT RDATA must contain at least one character-string")
        chunks: list[bytes] = []
        pos = 0
        while pos < len(rdata):
            slen = rdata[pos]
            pos += 1
            if pos + slen > len(rdata):
                raise DnsRdataError("TXT character-string exceeds RDLENGTH")
            chunks.append(bytes(rdata[pos : pos + slen]))
            pos += slen
        return chunks

    raise DnsRdataError(f"unsupported DNS RR type: {rtype}")
