      if (!actor || !actor.userId || !actor.orgId) {
        res.status(401).json({ error: "unauthenticated" });
        return;
      }

      const resource = await loadResource(req);
      if (!resource || resource.orgId !== actor.orgId) {
        res.status(404).json({ error: "resource_not_found" });
        return;
      }

      const isRead = SAFE_READ_METHODS.has(req.method.toUpperCase());
      if (!isRead) {
        if (resource.frozen) {
          res.status(423).json({ error: "resource_frozen" });
          return;
        }
        const isOwner = resource.ownerId === actor.userId;
        const isAdmin = actor.roles.includes("org:admin");
        if (!isOwner && !isAdmin) {
          res.status(403).json({ error: "forbidden_mutation" });
          return;
        }
      }

      req.resource = resource;
      next();
    } catch (err) {
      next(err);
    }
  };
}
