impl ChainState {
    fn derive_pair(&self) -> ([u8; 32], [u8; 32]) {
        let mut h_msg = Sha256::new();
        h_msg.update([0x01u8]);
        h_msg.update(self.chain_key);
        h_msg.update(self.seq.to_be_bytes());
        let msg_key: [u8; 32] = h_msg.finalize().into();

        let mut h_next = Sha256::new();
        h_next.update([0x02u8]);
        h_next.update(self.chain_key);
        h_next.update(self.seq.to_be_bytes());
        let next_ck: [u8; 32] = h_next.finalize().into();

        (msg_key, next_ck)
    }

    fn nonce_and_aad(seq: u64, aad_ctx: &[u8]) -> ([u8; 12], Vec<u8>) {
        let mut nonce_bytes = [0u8; 12];
        nonce_bytes[4..12].copy_from_slice(&seq.to_be_bytes());
        let mut aad = Vec::with_capacity(8 + aad_ctx.len());
        aad.extend_from_slice(&seq.to_be_bytes());
        aad.extend_from_slice(aad_ctx);
        (nonce_bytes, aad)
    }

    pub fn seal_next(&mut self, aad_ctx: &[u8], pt: &[u8]) -> Result<Vec<u8>, RatchetError> {
        let next_seq = self.seq.checked_add(1).ok_or(RatchetError::CounterExhausted)?;
        let (mut msg_key, mut next_ck) = self.derive_pair();
        let (nonce_bytes, aad) = Self::nonce_and_aad(self.seq, aad_ctx);

        let cipher = ChaCha20Poly1305::new((&msg_key).into());
        msg_key.zeroize();
        let res = cipher
            .encrypt(Nonce::from_slice(&nonce_bytes), Payload { msg: pt, aad: &aad })
            .map_err(|_| RatchetError::DecryptFailed);

        if res.is_ok() {
            self.chain_key.zeroize();
            self.chain_key.copy_from_slice(&next_ck);
            self.seq = next_seq;
        }
        next_ck.zeroize();
        res
    }

    pub fn open_next(&mut self, aad_ctx: &[u8], ct: &[u8]) -> Result<Vec<u8>, RatchetError> {
        let next_seq = self.seq.checked_add(1).ok_or(RatchetError::CounterExhausted)?;
        let (mut msg_key, mut next_ck) = self.derive_pair();
        let (nonce_bytes, aad) = Self::nonce_and_aad(self.seq, aad_ctx);

        let cipher = ChaCha20Poly1305::new((&msg_key).into());
        msg_key.zeroize();
        let pt = cipher
            .decrypt(Nonce::from_slice(&nonce_bytes), Payload { msg: ct, aad: &aad })
            .map_err(|_| {
                next_ck.zeroize();
                RatchetError::DecryptFailed
            })?;

        self.chain_key.zeroize();
        self.chain_key.copy_from_slice(&next_ck);
        next_ck.zeroize();
        self.seq = next_seq;
        Ok(pt)
    }
}
