func IdempotentTransferHandler(hmacKey []byte, store IdemStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		callerID := r.Header.Get("X-Caller-ID")
		idemKey := r.Header.Get("Idempotency-Key")
		if callerID == "" || len(idemKey) < 8 || len(idemKey) > 128 {
			http.Error(w, "missing caller or idempotency key", http.StatusBadRequest)
			return
		}

		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 256<<10))
		if err != nil {
			http.Error(w, "invalid or oversized request body", http.StatusBadRequest)
			return
		}

		bodySum := sha256.Sum256(body)
		mac := hmac.New(sha256.New, hmacKey)
		mac.Write([]byte(callerID))
		mac.Write([]byte{0})
		mac.Write([]byte(idemKey))
		mac.Write([]byte{0})
		mac.Write([]byte(hex.EncodeToString(bodySum[:])))
		fp := mac.Sum(nil)

		ctx := r.Context()
		existing, err := store.Load(ctx, callerID, idemKey)
		if err != nil {
			if errors.Is(err, context.Canceled) {
				w.WriteHeader(499)
				return
			}
			http.Error(w, "idempotency store lookup failed", http.StatusInternalServerError)
			return
		}

		if existing != nil {
			if !hmac.Equal(existing.Fingerprint, fp) {
				http.Error(w, "idempotency key reused with different payload", http.StatusUnprocessableEntity)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			w.Header().Set("Idempotent-Replayed", "true")
			w.WriteHeader(existing.StatusCode)
			_, _ = w.Write(existing.RespJSON)
			return
		}

		outcome, err := store.ExecuteAndSave(ctx, callerID, idemKey, fp, body)
		if err != nil {
			if errors.Is(err, context.Canceled) {
				w.WriteHeader(499)
				return
			}
			http.Error(w, "transfer execution failed", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(outcome.StatusCode)
		_, _ = w.Write(outcome.RespJSON)
	}
}
