fn parse_octal_usize(field: &[u8]) -> Result<usize, TarError> {
    let trimmed_start = field
        .iter()
        .position(|&b| b != b' ')
        .unwrap_or(field.len());
    let active = &field[trimmed_start..];
    let end = active
        .iter()
        .position(|&b| b == 0 || b == b' ')
        .unwrap_or(active.len());
    let digits = &active[..end];
    if digits.is_empty() {
        return Ok(0);
    }
    let mut acc = 0usize;
    for &b in digits {
        if !(b'0'..=b'7').contains(&b) {
            return Err(TarError::InvalidOctalSize);
        }
        acc = acc
            .checked_mul(8)
            .and_then(|v| v.checked_add((b - b'0') as usize))
            .ok_or(TarError::SizeOverflow)?;
    }
    Ok(acc)
}

pub fn parse_ustar_entry<'a>(archive: &'a [u8], offset: usize) -> Result<Option<TarEntry<'a>>, TarError> {
    let hdr_end = offset.checked_add(512).ok_or(TarError::SizeOverflow)?;
    let hdr = archive.get(offset..hdr_end).ok_or(TarError::Truncated)?;

    if hdr.iter().all(|&b| b == 0) {
        return Ok(None);
    }
    if &hdr[257..262] != b"ustar" {
        return Err(TarError::BadMagic);
    }

    let name_len = hdr[..100].iter().position(|&b| b == 0).unwrap_or(100);
    let size = parse_octal_usize(&hdr[124..136])?;
    let data_end = hdr_end.checked_add(size).ok_or(TarError::SizeOverflow)?;
    let data = archive.get(hdr_end..data_end).ok_or(TarError::Truncated)?;

    let padded_size = size
        .checked_add(511)
        .map(|n| n & !511usize)
        .ok_or(TarError::SizeOverflow)?;
    let next_offset = hdr_end.checked_add(padded_size).ok_or(TarError::SizeOverflow)?;
    if next_offset > archive.len() {
        return Err(TarError::Truncated);
    }

    Ok(Some(TarEntry {
        name: &hdr[..name_len],
        data,
        next_offset,
    }))
}
