func VerifySlackSignature(signingSecret string, nowFn func() time.Time, next http.Handler) http.Handler {
	secretBytes := []byte(signingSecret)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tsStr := strings.TrimSpace(r.Header.Get("X-Slack-Request-Timestamp"))
		sigStr := strings.TrimSpace(r.Header.Get("X-Slack-Signature"))
		if tsStr == "" || !strings.HasPrefix(sigStr, "v0=") {
			http.Error(w, "missing slack signature headers", http.StatusUnauthorized)
			return
		}

		tsUnix, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil {
			http.Error(w, "invalid slack timestamp", http.StatusBadRequest)
			return
		}
		skew := nowFn().Sub(time.Unix(tsUnix, 0))
		if skew < -5*time.Minute || skew > 5*time.Minute {
			http.Error(w, "expired slack timestamp", http.StatusUnauthorized)
			return
		}

		gotMAC, err := hex.DecodeString(strings.TrimPrefix(sigStr, "v0="))
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "malformed slack signature", http.StatusUnauthorized)
			return
		}

		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 512<<10))
		if err != nil {
			http.Error(w, "invalid request body", http.StatusBadRequest)
			return
		}

		mac := hmac.New(sha256.New, secretBytes)
		mac.Write([]byte("v0:"))
		mac.Write([]byte(tsStr))
		mac.Write([]byte(":"))
		mac.Write(body)
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "slack signature mismatch", http.StatusUnauthorized)
			return
