export const requireMtlsCertBoundJwt: onRequestHookHandler = async (
  req: FastifyRequest,
  reply: FastifyReply,
) => {
  const expectedThumbprint = req.jwtClaims?.cnf?.["x5t#S256"];
  if (!expectedThumbprint) {
    return reply.code(401).send({ error: "missing_cnf_x5t_s256_claim" });
  }

  const tlsSock = req.raw.socket as TLSSocket;
  if (!tlsSock.encrypted || !tlsSock.authorized) {
    return reply.code(401).send({ error: "unverified_mtls_client_certificate" });
  }

  const peerCert = tlsSock.getPeerCertificate(false);
  if (!peerCert || !Buffer.isBuffer(peerCert.raw) || peerCert.raw.length === 0) {
    return reply.code(401).send({ error: "missing_peer_certificate_der" });
  }

  const actualThumbprint = createHash("sha256").update(peerCert.raw).digest("base64url");
  const actualBuf = Buffer.from(actualThumbprint, "utf8");
  const expectedBuf = Buffer.from(expectedThumbprint, "utf8");

  if (actualBuf.length !== expectedBuf.length || !timingSafeEqual(actualBuf, expectedBuf)) {
    return reply.code(403).send({ error: "certificate_thumbprint_mismatch" });
  }
};
