fn canonical_checkpoint_bytes(cp: &Checkpoint<'_>) -> Vec<u8> {
    let orig = cp.origin.as_bytes();
    let mut msg = Vec::with_capacity(11 + 4 + orig.len() + 8 + 8 + 32);
