impl<'a> RingView<'a> {
    pub fn readable_slices(&self) -> Result<(&'a [u8], &'a [u8]), RingSliceError> {
        let cap = self.buf.len();
        if !cap.is_power_of_two() {
            return Err(RingSliceError::InvalidCapacity);
        }
        let avail = self
            .write_idx
            .checked_sub(self.read_idx)
            .ok_or(RingSliceError::CorruptedIndices)?;
        if avail > cap {
            return Err(RingSliceError::CorruptedIndices);
        }
        if avail == 0 {
            return Ok((&[], &[]));
        }

        let start = self.read_idx & (cap - 1);
        let until_end = cap - start;
        if avail <= until_end {
            let end = start.checked_add(avail).ok_or(RingSliceError::CorruptedIndices)?;
            let first = self.buf.get(start..end).ok_or(RingSliceError::CorruptedIndices)?;
            Ok((first, &[]))
        } else {
            let first = self.buf.get(start..cap).ok_or(RingSliceError::CorruptedIndices)?;
            let wrap_len = avail - until_end;
            let second = self.buf.get(..wrap_len).ok_or(RingSliceError::CorruptedIndices)?;
            Ok((first, second))
        }
    }
}
