```go
func SanitizeAndSignGateway(hmacSecret []byte, nowFn func() time.Time, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		outReq := r.Clone(r.Context())
		h := outReq.Header

		for _, connVal := range h.Values("Connection") {
			for _, token := range strings.Split(connVal, ",") {
				if name := strings.TrimSpace(token); name != "" {
					h.Del(name)
				}
			}
		}
		for _, hb := range hopByHopHeaders {
			h.Del(hb)
		}

		h.Del("X-Gateway-Timestamp")
		h.Del("X-Gateway-HMAC")

		tsStr := strconv.FormatInt(nowFn().Unix(), 10)
		mac := hmac.New(sha256.New, hmacSecret)
		mac.Write([]byte(outReq.Method))
		mac.Write([]byte("\n"))
		mac.Write([]byte(outReq.URL.RequestURI()))
		mac.Write([]byte("\n"))
		mac.Write([]byte(tsStr))

		h.Set("X-Gateway-Timestamp", tsStr)
		h.Set("X-Gateway-HMAC", hex.EncodeToString(mac.Sum(nil)))
		next.ServeHTTP(w, outReq)
	})
}
