```python
def read_sqlite_varint(buf: bytes, pos: int) -> tuple[int, int]:
    if pos < 0 or pos >= len(buf):
        raise SqliteRecordError("varint EOF")
    acc = 0
    for idx in range(9):
        if pos + idx >= len(buf):
            raise SqliteRecordError("truncated sqlite varint")
        b = buf[pos + idx]
        if idx == 8:
            acc = (acc << 8) | b
            return acc, pos + 9
        acc = (acc << 7) | (b & 0x7F)
        if (b & 0x80) == 0:
            return acc, pos + idx + 1
    raise SqliteRecordError("unreachable")


def parse_sqlite_record(record: bytes) -> list[None | int | bytes | str]:
    hdr_len, pos = read_sqlite_varint(record, 0)
    if hdr_len < pos or hdr_len > len(record):
        raise SqliteRecordError("invalid sqlite record header size")

    serial_types: list[int] = []
    while pos < hdr_len:
        st, pos = read_sqlite_varint(record, pos)
        serial_types.append(st)
    if pos != hdr_len:
        raise SqliteRecordError("varint overran sqlite record header")

    body_pos = hdr_len
    values: list[None | int | bytes | str] = []
    for st in serial_types:
        if st == 0:
            values.append(None)
        elif st == 8:
            values.append(0)
        elif st == 9:
            values.append(1)
        elif st in (1, 2, 4):
            fmt, width = {1: (">b", 1), 2: (">h", 2), 4: (">i", 4)}[st]
            if body_pos + width > len(record):
                raise SqliteRecordError("truncated integer column")
            (val,) = struct.unpack_from(fmt, record, body_pos)
            body_pos += width
            values.append(val)
        elif st >= 12 and st % 2 == 0:
            n = (st - 12) // 2
            if body_pos + n > len(record):
                raise SqliteRecordError("truncated blob column")
            values.append(record[body_pos : body_pos + n])
            body_pos += n
        elif st >= 13 and st % 2 == 1:
            n = (st - 13) // 2
            if body_pos + n > len(record):
                raise SqliteRecordError("truncated text column")
            values.append(record[body_pos : body_pos + n].decode("utf-8", errors="strict"))
            body_pos += n
        else:
            raise SqliteRecordError(f"unsupported sqlite serial type: {st}")

    return values
