export function adminSubnetGuard(
  allowedCidrs: readonly string[],
  trustedProxyHops: number,
): MiddlewareHandler {
  if (!Number.isInteger(trustedProxyHops) || trustedProxyHops < 1) {
    throw new RangeError("trustedProxyHops must be an integer >= 1");
  }

  const parsedCidrs = allowedCidrs.map((cidr) => {
    const [addr, prefixStr] = cidr.split("/");
    const base = ipv4ToUint32(addr ?? "");
    const prefix = Number(prefixStr);
    if (base === null || !Number.isInteger(prefix) || prefix < 0 || prefix > 32) {
      throw new Error(`Invalid IPv4 CIDR: ${cidr}`);
    }
    const mask = prefix === 0 ? 0 : (~0 << (32 - prefix)) >>> 0;
    return { network: (base & mask) >>> 0, mask };
  });

  return async (c, next) => {
    const xff = c.req.header("X-Forwarded-For");
    if (!xff) {
      return c.json({ error: "missing_client_ip" }, 403);
    }

    const hops = xff
      .split(",")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

    const clientIdx = Math.max(0, hops.length - trustedProxyHops);
    const clientIp = hops[clientIdx];
    const ipNum = clientIp ? ipv4ToUint32(clientIp) : null;
    if (ipNum === null) {
      return c.json({ error: "invalid_client_ipv4" }, 403);
    }

    const allowed = parsedCidrs.some(({ network, mask }) => ((ipNum & mask) >>> 0) === network);
    if (!allowed) {
      return c.json({ error: "ip_not_in_allowed_subnet" }, 403);
    }

    await next();
  };
}
