def _b64u_enc(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64u_dec(text: str) -> bytes:
    pad = "=" * ((4 - len(text) % 4) % 4)
    return base64.urlsafe_b64decode(text + pad)


def _pack_grant(g: CapabilityGrant) -> bytes:
    parts = [g.subject.encode("utf-8"), g.action.encode("utf-8"), g.resource.encode("utf-8")]
    out = bytearray()
    for p in parts:
        if len(p) > 0xFFFF:
            raise ValueError("field too long")
        out.extend(struct.pack(">H", len(p)))
        out.extend(p)
    out.extend(struct.pack(">Q", g.exp_unix))
    return bytes(out)


def _unpack_grant(raw: bytes) -> CapabilityGrant:
    pos = 0
    fields: list[str] = []
    for _ in range(3):
        if pos + 2 > len(raw):
            raise CapabilityVerifyError("truncated grant field length")
        (flen,) = struct.unpack_from(">H", raw, pos)
        pos += 2
        if pos + flen > len(raw):
            raise CapabilityVerifyError("truncated grant field bytes")
        fields.append(raw[pos : pos + flen].decode("utf-8", errors="strict"))
        pos += flen
    if pos + 8 != len(raw):
        raise CapabilityVerifyError("invalid trailing bytes in grant")
    (exp_unix,) = struct.unpack_from(">Q", raw, pos)
    return CapabilityGrant(fields[0], fields[1], fields[2], exp_unix)


def mint_capability(sk: Ed25519PrivateKey, grant: CapabilityGrant) -> str:
    body = _pack_grant(grant)
    sig = sk.sign(DOMAIN_TAG + body)
    return f"{_b64u_enc(body)}.{_b64u_enc(sig)}"


def verify_capability(pk: Ed25519PublicKey, token: str, now_unix: int) -> CapabilityGrant:
    pieces = token.split(".")
    if len(pieces) != 2:
        raise CapabilityVerifyError("malformed capability token")
    try:
        body = _b64u_dec(pieces[0])
        sig = _b64u_dec(pieces[1])
    except Exception as exc:
        raise CapabilityVerifyError("invalid base64url encoding") from exc

    if len(sig) != 64:
        raise CapabilityVerifyError("invalid ed25519 signature length")
    try:
        pk.verify(sig, DOMAIN_TAG + body)
    except InvalidSignature as exc:
        raise CapabilityVerifyError("signature verification failed") from exc

    grant = _unpack_grant(body)
    if grant.exp_unix <= now_unix:
        raise CapabilityVerifyError("capability token expired")
    return grant
