func StreamNDJSONHandler(sink RecordSink) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		ctx := r.Context()
		r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
		scanner := bufio.NewScanner(r.Body)
		scanner.Buffer(make([]byte, 4096), maxLineBytes)

		lineNo := 0
		accepted := 0
		for scanner.Scan() {
			lineNo++
			if err := ctx.Err(); err != nil {
				if errors.Is(err, context.DeadlineExceeded) {
					http.Error(w, "request deadline exceeded", http.StatusRequestTimeout)
				} else {
					w.WriteHeader(499)
				}
				return
			}

			raw := strings.TrimSpace(scanner.Text())
			if raw == "" {
				continue
			}

			var rec map[string]any
			if err := json.Unmarshal([]byte(raw), &rec); err != nil || rec == nil {
				http.Error(w, fmt.Sprintf("invalid JSON object at line %d", lineNo), http.StatusBadRequest)
				return
			}
			if err := sink(ctx, lineNo, rec); err != nil {
				if errors.Is(err, context.Canceled) {
					w.WriteHeader(499)
					return
				}
				http.Error(w, fmt.Sprintf("sink rejected line %d", lineNo), http.StatusUnprocessableEntity)
				return
			}
			accepted++
		}

		if err := scanner.Err(); err != nil {
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				http.Error(w, "ndjson body too large", http.StatusRequestEntityTooLarge)
				return
			}
			if errors.Is(err, bufio.ErrTooLong) {
				http.Error(w, fmt.Sprintf("line %d exceeds 64 KiB limit", lineNo+1), http.StatusBadRequest)
				return
			}
			http.Error(w, "stream read error", http.StatusBadRequest)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = fmt.Fprintf(w, `{"accepted":%d}`, accepted)
	}
}
