def _parse_part_headers(raw_hdr_bytes: bytes) -> dict[str, str]:
    hdrs: dict[str, str] = {}
    for line in raw_hdr_bytes.decode("latin-1").split("\r\n"):
        if not line:
            continue
        if ":" not in line:
            raise MultipartLimitError("malformed multipart header line")
        k, v = line.split(":", 1)
        hdrs[k.strip().lower()] = v.strip()
    return hdrs


def parse_multipart_form(
    raw: bytes,
    boundary: str,
    max_parts: int = 16,
    max_part_bytes: int = 1_048_576,
) -> list[FormPart]:
    if not boundary or "\r" in boundary or "\n" in boundary:
        raise MultipartLimitError("invalid multipart boundary")

    dash_b = ("--" + boundary).encode("ascii")
    end_marker = dash_b + b"--"
    end_idx = raw.find(end_marker)
    if end_idx == -1:
        raise MultipartLimitError("missing closing multipart boundary")

    first_idx = raw.find(dash_b + b"\r\n")
    if first_idx == -1 or first_idx > end_idx:
        if raw.startswith(end_marker):
            return []
        raise MultipartLimitError("missing opening multipart boundary")

    core = raw[first_idx + len(dash_b) + 2 : end_idx]
    if not core.endswith(b"\r\n"):
        raise MultipartLimitError("missing CRLF before closing boundary")
    core = core[:-2]

    chunks = core.split(b"\r\n" + dash_b + b"\r\n")
    if len(chunks) > max_parts:
        raise MultipartLimitError(f"exceeded max_parts ({max_parts})")

    results: list[FormPart] = []
    for chunk in chunks:
        sep = chunk.find(b"\r\n\r\n")
        if sep == -1:
            raise MultipartLimitError("part missing CRLFCRLF header separator")
        hdr_map = _parse_part_headers(chunk[:sep])
        payload = chunk[sep + 4 :]
        if len(payload) > max_part_bytes:
            raise MultipartLimitError(f"part exceeded max_part_bytes ({max_part_bytes})")

        disp = hdr_map.get("content-disposition", "")
        m = Message()
        m["Content-Disposition"] = disp
        if m.get_content_disposition() != "form-data":
            raise MultipartLimitError("expected form-data Content-Disposition")
        field_name = m.get_param("name", header="Content-Disposition")
        if not isinstance(field_name, str) or not field_name:
            raise MultipartLimitError("missing form-data name parameter")
        fname = m.get_param("filename", header="Content-Disposition")
        results.append(
            FormPart(
                name=field_name,
                filename=fname if isinstance(fname, str) else None,
                content_type=hdr_map.get("content-type", "text/plain"),
                data=payload,
            )
        )

    return results
