export function requireRecentMfa(
  maxAgeSec: number,
  nowSecFn = () => Math.floor(Date.now() / 1000),
): RequestHandler {
  if (!Number.isInteger(maxAgeSec) || maxAgeSec <= 0) {
    throw new RangeError("maxAgeSec must be a positive integer");
  }

  return (req: Request, res: Response, next: NextFunction): void => {
    const claims = req.authClaims;
    if (!claims || !claims.sub) {
      res.status(401).json({ error: "unauthenticated" });
      return;
    }

    const hasMfa = Array.isArray(claims.amr) && claims.amr.some((method) => STRONG_AMR.has(method));
    const authTime = claims.auth_time;
    const nowSec = nowSecFn();
    const ageSec = typeof authTime === "number" ? nowSec - authTime : Number.POSITIVE_INFINITY;
    const freshEnough = Number.isFinite(ageSec) && ageSec >= -5 && ageSec <= maxAgeSec;

    if (!hasMfa || !freshEnough) {
      res.setHeader(
        "WWW-Authenticate",
        `Bearer error="insufficient_user_authentication", max_age="${maxAgeSec}"`,
      );
      res.status(401).json({
        error: "step_up_mfa_required",
        has_mfa: hasMfa,
        max_age_seconds: maxAgeSec,
      });
      return;
    }

    next();
  };
}
