[[nodiscard]] bool slip_decode_frame(
    const uint8_t *in_buf,
    size_t in_len,
    uint8_t *out_buf,
    size_t out_cap,
    size_t *out_len,
    size_t *in_consumed
) {
    if (in_buf == nullptr || out_buf == nullptr || out_len == nullptr || in_consumed == nullptr) {
        return false;
    }
    *out_len = 0;
    *in_consumed = 0;

    size_t pos = 0;
    while (pos < in_len && in_buf[pos] == SLIP_END) {
        pos += 1u;
    }
    if (pos >= in_len) {
        return false;
    }

    size_t written = 0;
    while (pos < in_len) {
        uint8_t b = in_buf[pos++];
        if (b == SLIP_END) {
            *out_len = written;
            *in_consumed = pos;
            return true;
        }

        uint8_t decoded_byte = b;
        if (b == SLIP_ESC) {
            if (pos >= in_len) {
                return false; // truncated escape
            }
            uint8_t esc = in_buf[pos++];
            if (esc == SLIP_ESC_END) {
                decoded_byte = SLIP_END;
            } else if (esc == SLIP_ESC_ESC) {
                decoded_byte = SLIP_ESC;
            } else {
                return false; // illegal SLIP escape code
            }
        }

        if (written >= out_cap) {
            return false;
        }
        out_buf[written++] = decoded_byte;
    }

    return false; // missing terminating SLIP_END
