```go
func wrapAAD(purpose, recordID string) []byte {
	aad := make([]byte, 0, 12+len(purpose)+len(recordID))
	aad = append(aad, "dekwrap-v1\x00"...)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(purpose)))
	aad = append(aad, b[:]...)
	aad = append(aad, purpose...)
	binary.BigEndian.PutUint32(b[:], uint32(len(recordID)))
	aad = append(aad, b[:]...)
	aad = append(aad, recordID...)
	return aad
}

func WrapDEK(kek, dek []byte, purpose, recordID string) ([]byte, error) {
	if len(kek) != 32 || len(dek) != 32 {
		return nil, ErrInvalidKeySize
	}
	blk, err := aes.NewCipher(kek)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(blk)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	out := make([]byte, len(nonce), len(nonce)+32+gcm.Overhead())
	copy(out, nonce)
	return gcm.Seal(out, nonce, dek, wrapAAD(purpose, recordID)), nil
}

func UnwrapDEK(kek, wrapped []byte, purpose, recordID string) ([]byte, error) {
	if len(kek) != 32 {
		return nil, ErrInvalidKeySize
	}
	blk, err := aes.NewCipher(kek)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(blk)
	if err != nil {
		return nil, err
	}
	expectedLen := gcm.NonceSize() + 32 + gcm.Overhead()
	if len(wrapped) != expectedLen {
		return nil, ErrUnwrapFailed
	}
	nonce := wrapped[:gcm.NonceSize()]
	ct := wrapped[gcm.NonceSize():]
	dek, err := gcm.Open(nil, nonce, ct, wrapAAD(purpose, recordID))
	if err != nil || len(dek) != 32 {
		return nil, ErrUnwrapFailed
	}
	return dek, nil
