			return
		}

		cookie, err := r.Cookie("__Host-csrf")
		hdrTok := strings.TrimSpace(r.Header.Get("X-CSRF-Token"))
		if err != nil || cookie.Value == "" || hdrTok == "" {
			http.Error(w, "missing csrf token", http.StatusForbidden)
			return
		}
		if !hmac.Equal([]byte(cookie.Value), []byte(hdrTok)) {
			http.Error(w, "csrf cookie/header mismatch", http.StatusForbidden)
			return
		}

		parts := strings.Split(hdrTok, ".")
		if len(parts) != 2 || len(parts[0]) < 32 {
			http.Error(w, "malformed csrf token", http.StatusForbidden)
			return
		}
		if _, err := hex.DecodeString(parts[0]); err != nil {
			http.Error(w, "invalid csrf nonce", http.StatusForbidden)
			return
		}
		gotMAC, err := hex.DecodeString(parts[1])
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "invalid csrf mac", http.StatusForbidden)
			return
		}

		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(sessionID))
		mac.Write([]byte(":"))
		mac.Write([]byte(parts[0]))
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "csrf session binding failed", http.StatusForbidden)
			return
		}

		next.ServeHTTP(w, r)
