def pop_netstrings(buf: bytes, max_frame_bytes: int = 65_536) -> tuple[list[bytes], bytes]:
    frames: list[bytes] = []
    pos = 0
    total = len(buf)

    while pos < total:
        colon_idx = buf.find(b":", pos, pos + 12)
        if colon_idx == -1:
            rem = buf[pos : pos + 12]
            if not rem.isdigit():
                raise NetstringError("non-digit byte in netstring length prefix")
            if len(rem) > 1 and rem[0] == ord("0"):
                raise NetstringError("leading zero in netstring length")
            if len(rem) >= 11:
                raise NetstringError("netstring length prefix too long")
            break  # partial length prefix; wait for more bytes

        len_bytes = buf[pos:colon_idx]
        if not len_bytes or not len_bytes.isdigit():
            raise NetstringError("invalid netstring length prefix")
        if len(len_bytes) > 1 and len_bytes[0] == ord("0"):
            raise NetstringError("leading zero forbidden in DJB netstring")

        frame_len = int(len_bytes)
        if frame_len > max_frame_bytes:
            raise NetstringError(f"netstring length {frame_len} exceeds {max_frame_bytes}")

        comma_idx = colon_idx + 1 + frame_len
        if comma_idx >= total:
            break  # incomplete frame body or trailing comma; retain from pos

        if buf[comma_idx] != ord(","):
            raise NetstringError("missing trailing comma delimiter")

        frames.append(buf[colon_idx + 1 : comma_idx])
        pos = comma_idx + 1

    return frames, buf[pos:]
