```ts
function estimateQueryCost(rawQuery: string): number | null {
  const stripped = rawQuery
    .replace(/"""[\s\S]*?"""|"(?:\\.|[^"\\])*"/g, '""')
    .replace(/#[^\r\n]*/g, "");

  let depth = 0;
  let maxDepth = 0;
  for (const ch of stripped) {
    if (ch === "{") {
      depth++;
      if (depth > maxDepth) maxDepth = depth;
    } else if (ch === "}") {
      depth--;
      if (depth < 0) return null;
    }
  }
  if (depth !== 0 || maxDepth === 0) return null;

  const aliasCount = (stripped.match(/\b[_A-Za-z][_0-9A-Za-z]*\s*:/g) ?? []).length;
  const tokenCount = (stripped.match(/\b[_A-Za-z][_0-9A-Za-z]*\b/g) ?? []).length;
  return tokenCount + aliasCount * 4 + maxDepth * 3;
}

export function createGraphqlCostPreHandler(cfg: GraphqlCostConfig): preHandlerHookHandler {
  const windows = new Map<string, { spent: number; resetAtMs: number }>();
  const nowOf = cfg.nowMsFn ?? (() => Date.now());

  return async (req: FastifyRequest, reply: FastifyReply) => {
    const orgId = cfg.getOrgId(req);
    if (!orgId) {
      return reply.code(401).send({ error: "missing_org_context" });
    }

    const body = req.body as { query?: unknown } | undefined;
    if (!body || typeof body.query !== "string" || body.query.length === 0) {
      return reply.code(400).send({ error: "missing_graphql_query" });
    }

    const cost = estimateQueryCost(body.query);
    if (cost === null) {
      return reply.code(400).send({ error: "malformed_graphql_braces" });
    }
    if (cost > cfg.maxQueryCost) {
      return reply.code(400).send({ error: "graphql_query_too_complex", cost, max: cfg.maxQueryCost });
    }

    const nowMs = nowOf();
    let win = windows.get(orgId);
    if (!win || nowMs >= win.resetAtMs) {
      win = { spent: 0, resetAtMs: nowMs + 60_000 };
    }

    if (win.spent + cost > cfg.orgBudgetPerMin) {
      windows.set(orgId, win);
      const retrySec = Math.max(1, Math.ceil((win.resetAtMs - nowMs) / 1000));
      reply.header("Retry-After", String(retrySec));
      return reply.code(429).send({ error: "graphql_cost_budget_exceeded", cost });
    }

    win.spent += cost;
    windows.set(orgId, win);
  };
}
```

