function cookieAad(cookieName: string, hostDomain: string): Buffer {
  const nameBuf = Buffer.from(cookieName, "utf8");
  const hostBuf = Buffer.from(hostDomain.trim().toLowerCase(), "utf8");
  const aad = Buffer.allocUnsafe(8 + 2 + nameBuf.length + 2 + hostBuf.length);
  aad.write("ck-v1\x00\x00\x00", 0, "binary");
  aad.writeUInt16BE(nameBuf.length, 8);
  nameBuf.copy(aad, 10);
  aad.writeUInt16BE(hostBuf.length, 10 + nameBuf.length);
  hostBuf.copy(aad, 12 + nameBuf.length);
  return aad;
}

export function sealCookieValue(
  key: Buffer,
  cookieName: string,
  hostDomain: string,
  plaintextUtf8: string,
): string {
  if (key.length !== 32) {
    throw new Error("chacha20-poly1305 requires a 32-byte key");
  }
  const iv = randomBytes(NONCE_BYTES);
  const cipher = createCipheriv("chacha20-poly1305", key, iv, { authTagLength: TAG_BYTES });
  cipher.setAAD(cookieAad(cookieName, hostDomain), { plaintextLength: Buffer.byteLength(plaintextUtf8, "utf8") });
  const ct = Buffer.concat([cipher.update(plaintextUtf8, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, ct]).toString("base64url");
}

export function unsealCookieValue(
  key: Buffer,
  cookieName: string,
  hostDomain: string,
  encodedCookie: string,
): string | null {
  if (key.length !== 32 || !encodedCookie) {
    return null;
  }
  try {
    const raw = Buffer.from(encodedCookie, "base64url");
    if (raw.length < NONCE_BYTES + TAG_BYTES) {
      return null;
    }
    const iv = raw.subarray(0, NONCE_BYTES);
    const tag = raw.subarray(NONCE_BYTES, NONCE_BYTES + TAG_BYTES);
    const ct = raw.subarray(NONCE_BYTES + TAG_BYTES);

    const decipher = createDecipheriv("chacha20-poly1305", key, iv, { authTagLength: TAG_BYTES });
    decipher.setAAD(cookieAad(cookieName, hostDomain), { plaintextLength: ct.length });
    decipher.setAuthTag(tag);
