pub fn decode_cbor_indef_bytes(
    input: &[u8],
    max_total_len: usize,
) -> Result<(Vec<u8>, usize), CborBytesError> {
    let &first = input.first().ok_or(CborBytesError::UnexpectedEof)?;
    if first != 0x5f {
        return Err(CborBytesError::ExpectedIndefBytes(first));
    }

    let mut pos = 1usize;
    let mut out = Vec::new();

    loop {
        let &ib = input.get(pos).ok_or(CborBytesError::UnexpectedEof)?;
        pos = pos.checked_add(1).ok_or(CborBytesError::ExceedsBudget)?;
        if ib == 0xff {
            return Ok((out, pos));
        }

        let major = ib >> 5;
        let ai = ib & 0x1f;
        if major != 2 || ai > 26 {
            return Err(CborBytesError::InvalidChunkHeader(ib));
        }

        let chunk_len: usize = match ai {
            0..=23 => ai as usize,
            24 => {
                let &b = input.get(pos).ok_or(CborBytesError::UnexpectedEof)?;
                pos = pos.checked_add(1).ok_or(CborBytesError::ExceedsBudget)?;
                b as usize
            }
            25 => {
                let end = pos.checked_add(2).ok_or(CborBytesError::ExceedsBudget)?;
                let s = input.get(pos..end).ok_or(CborBytesError::UnexpectedEof)?;
                pos = end;
                u16::from_be_bytes([s[0], s[1]]) as usize
            }
            26 => {
                let end = pos.checked_add(4).ok_or(CborBytesError::ExceedsBudget)?;
                let s = input.get(pos..end).ok_or(CborBytesError::UnexpectedEof)?;
                pos = end;
                u32::from_be_bytes([s[0], s[1], s[2], s[3]]) as usize
            }
            _ => return Err(CborBytesError::InvalidChunkHeader(ib)),
        };

        let new_total = out
            .len()
            .checked_add(chunk_len)
            .ok_or(CborBytesError::ExceedsBudget)?;
        if new_total > max_total_len {
            return Err(CborBytesError::ExceedsBudget);
        }

        let chunk_end = pos.checked_add(chunk_len).ok_or(CborBytesError::ExceedsBudget)?;
        let slice = input.get(pos..chunk_end).ok_or(CborBytesError::UnexpectedEof)?;
        out.extend_from_slice(slice);
        pos = chunk_end;
    }
}
