_HEX_ESC_RE = re.compile(r"\\x([0-9a-fA-F]{2})")


def _decode_zeek_sep(raw: str) -> str:
    return _HEX_ESC_RE.sub(lambda m: chr(int(m.group(1), 16)), raw)


def _cast_zeek_val(
    raw: str,
    ztype: str,
    empty_tok: str,
    unset_tok: str,
    set_sep: str,
) -> Any:
    if raw == unset_tok:
        return None
    if ztype.startswith(("set[", "vector[")):
        if raw == empty_tok:
            return []
        return raw.split(set_sep)
    if raw == empty_tok:
        return ""
    if ztype in ("count", "port", "int"):
        return int(raw)
    if ztype in ("time", "interval", "double"):
        return float(raw)
    if ztype == "bool":
        if raw == "T":
            return True
        if raw == "F":
            return False
        raise ValueError(f"invalid zeek bool: {raw}")
    return raw


def parse_zeek_tsv(lines: list[str]) -> list[dict[str, Any]]:
    sep = "\t"
    set_sep = ","
    empty_tok = "(empty)"
    unset_tok = "-"
    fields: list[str] = []
    types: list[str] = []
    rows: list[dict[str, Any]] = []

    for raw_line in lines:
        line = raw_line.rstrip("\r\n")
        if not line:
            continue
        if line.startswith("#separator "):
            sep = _decode_zeek_sep(line[len("#separator ") :])
            continue
        if line.startswith("#"):
            parts = line.split(sep)
            directive = parts[0]
            if directive == "#set_separator" and len(parts) >= 2:
                set_sep = _decode_zeek_sep(parts[1])
            elif directive == "#empty_field" and len(parts) >= 2:
                empty_tok = parts[1]
            elif directive == "#unset_field" and len(parts) >= 2:
                unset_tok = parts[1]
            elif directive == "#fields":
                fields = parts[1:]
            elif directive == "#types":
                types = parts[1:]
            continue

        if not fields or len(fields) != len(types):
            raise ValueError("zeek data row encountered before valid #fields/#types")
        vals = line.split(sep)
        if len(vals) != len(fields):
            raise ValueError("column count mismatch in zeek TSV row")
        rows.append(
            {
                fname: _cast_zeek_val(v, ftype, empty_tok, unset_tok, set_sep)
                for fname, ftype, v in zip(fields, types, vals)
            }
        )

    return rows
