```ts
export function idempotencyLockMiddleware(
  getCallerId: (c: Parameters<MiddlewareHandler>[0]) => string | undefined,
): MiddlewareHandler {
  const entries = new Map<string, Entry>();

  return async (c, next) => {
    if (c.req.method.toUpperCase() !== "POST") {
      await next();
      return;
    }

    const callerId = getCallerId(c);
    if (!callerId) {
      return c.json({ error: "unauthenticated" }, 401);
    }

    const idemKey = c.req.header("Idempotency-Key")?.trim();
    if (!idemKey || idemKey.length < 8 || idemKey.length > 128) {
      return c.json({ error: "invalid_idempotency_key" }, 400);
    }

    const rawBytes = Buffer.from(await c.req.raw.clone().arrayBuffer());
    const bodyHash = createHash("sha256").update(rawBytes).digest("hex");
    const compositeKey = `${callerId}:${idemKey}`;

    const existing = entries.get(compositeKey);
    if (existing) {
      if (existing.state === "in_flight") {
        return c.json({ error: "idempotency_request_in_flight" }, 409);
      }
      if (existing.bodyHash !== bodyHash) {
        return c.json({ error: "idempotency_payload_mismatch" }, 422);
      }
      return c.body(existing.respText, existing.status as 200, {
        "Content-Type": existing.contentType,
        "Idempotent-Replayed": "true",
      });
    }

    entries.set(compositeKey, { state: "in_flight", bodyHash });
    try {
      await next();
      if (c.res.status >= 500) {
        entries.delete(compositeKey);
        return;
      }
      const cloned = c.res.clone();
      const respText = await cloned.text();
      const contentType = cloned.headers.get("Content-Type") ?? "application/json";
      entries.set(compositeKey, {
        state: "done",
        bodyHash,
        status: c.res.status,
        respText,
        contentType,
      });
    } catch (err) {
      entries.delete(compositeKey);
      throw err;
    }
  };
}
```

