[[nodiscard]] bool parse_rtp_payload(const uint8_t *pkt, size_t pkt_len, rtp_view_t *out) {
    if (pkt == nullptr || out == nullptr || pkt_len < 12u) {
        return false;
    }

    uint8_t b0 = pkt[0];
    if ((b0 >> 6) != 2u) {
        return false;
    }
    bool has_padding = (b0 & 0x20u) != 0u;
    bool has_ext = (b0 & 0x10u) != 0u;
    size_t cc = (size_t)(b0 & 0x0Fu);

    size_t pos = 12u;
    size_t csrc_bytes = 0;
    if (ckd_mul(&csrc_bytes, cc, (size_t)4u) || ckd_add(&pos, pos, csrc_bytes) || pos > pkt_len) {
        return false;
    }

    if (has_ext) {
        size_t ext_hdr_end = 0;
        if (ckd_add(&ext_hdr_end, pos, (size_t)4u) || ext_hdr_end > pkt_len) {
            return false;
        }
        size_t ext_words = ((size_t)pkt[pos + 2u] << 8) | (size_t)pkt[pos + 3u];
        size_t ext_body = 0;
        if (ckd_mul(&ext_body, ext_words, (size_t)4u) || ckd_add(&pos, ext_hdr_end, ext_body) || pos > pkt_len) {
            return false;
        }
    }

    size_t end = pkt_len;
    if (has_padding) {
        if (pos >= end) {
            return false;
        }
        uint8_t pad_len = pkt[end - 1u];
        size_t rem = end - pos;
        if (pad_len == 0u || (size_t)pad_len > rem) {
            return false;
        }
        end -= (size_t)pad_len;
