    out->seq = ((uint16_t)pkt[2] << 8) | (uint16_t)pkt[3];
    out->ssrc = ((uint32_t)pkt[8] << 24) | ((uint32_t)pkt[9] << 16) | ((uint32_t)pkt[10] << 8) | (uint32_t)pkt[11];
    out->payload = pkt + pos;
    out->payload_len = end - pos;
    return true;
