fn build_cell_aad(table_name: &str, row_uuid: &[u8; 16], column_name: &str) -> Vec<u8> {
    let tbl = table_name.as_bytes();
    let col = column_name.as_bytes();
    let mut aad = Vec::with_capacity(10 + 4 + tbl.len() + 16 + 4 + col.len());
    aad.extend_from_slice(b"dbcell-v1\x00");
    aad.extend_from_slice(&(tbl.len() as u32).to_be_bytes());
    aad.extend_from_slice(tbl);
    aad.extend_from_slice(row_uuid);
    aad.extend_from_slice(&(col.len() as u32).to_be_bytes());
    aad.extend_from_slice(col);
    aad
}

pub fn encrypt_cell(
    key: &[u8; 32],
    table_name: &str,
    row_uuid: &[u8; 16],
    column_name: &str,
    plaintext: &[u8],
) -> Result<Vec<u8>, CellCipherError> {
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CellCipherError::AuthenticationFailed)?;
    let nonce = Aes256Gcm::generate_nonce(&mut OsRng);
    let aad = build_cell_aad(table_name, row_uuid, column_name);
    let ct = cipher
        .encrypt(&nonce, Payload { msg: plaintext, aad: &aad })
        .map_err(|_| CellCipherError::AuthenticationFailed)?;
    let mut blob = Vec::with_capacity(12 + ct.len());
    blob.extend_from_slice(nonce.as_slice());
    blob.extend_from_slice(&ct);
    Ok(blob)
}

pub fn decrypt_cell(
    key: &[u8; 32],
    table_name: &str,
    row_uuid: &[u8; 16],
    column_name: &str,
    blob: &[u8],
) -> Result<Vec<u8>, CellCipherError> {
    if blob.len() < 12 + 16 {
        return Err(CellCipherError::TruncatedBlob);
    }
    let (nonce_bytes, ct) = blob.split_at(12);
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| CellCipherError::AuthenticationFailed)?;
    let aad = build_cell_aad(table_name, row_uuid, column_name);
    cipher
        .decrypt(Nonce::from_slice(nonce_bytes), Payload { msg: ct, aad: &aad })
        .map_err(|_| CellCipherError::AuthenticationFailed)
}
