pub fn next_ipfix_set<'a>(
    msg_body: &'a [u8],
    cursor: &mut usize,
) -> Result<Option<IpfixSet<'a>>, IpfixSetError> {
    if *cursor == msg_body.len() {
        return Ok(None);
    }
    let hdr_end = cursor.checked_add(4).ok_or(IpfixSetError::Overflow)?;
    let hdr = msg_body.get(*cursor..hdr_end).ok_or(IpfixSetError::Truncated)?;

    let set_id = u16::from_be_bytes([hdr[0], hdr[1]]);
    let set_len = u16::from_be_bytes([hdr[2], hdr[3]]);
    if set_len < 4 {
        return Err(IpfixSetError::InvalidSetLength(set_len));
    }

    let set_end = cursor
        .checked_add(set_len as usize)
        .ok_or(IpfixSetError::Overflow)?;
    let records = msg_body.get(hdr_end..set_end).ok_or(IpfixSetError::Truncated)?;

    *cursor = set_end;
    Ok(Some(IpfixSet { set_id, records }))
}
