func AuthenticateAPIKey(serverPepper []byte, repo KeyRepository, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		auth := strings.TrimSpace(r.Header.Get("Authorization"))
		if !strings.HasPrefix(auth, "Bearer sk_live_") {
			http.Error(w, "missing api key", http.StatusUnauthorized)
			return
		}

		rest := strings.TrimPrefix(auth, "Bearer sk_live_")
		parts := strings.SplitN(rest, "_", 2)
		if len(parts) != 2 || len(parts[0]) < 6 || len(parts[1]) < 24 {
			http.Error(w, "malformed api key", http.StatusUnauthorized)
			return
		}
		keyID, rawSecret := parts[0], parts[1]

		lookupCtx, cancel := context.WithTimeout(r.Context(), 500*time.Millisecond)
		rec, err := repo.FindKey(lookupCtx, keyID)
		cancel()
		if err != nil {
			if errors.Is(r.Context().Err(), context.Canceled) {
				w.WriteHeader(499)
				return
			}
			if errors.Is(err, context.DeadlineExceeded) {
				http.Error(w, "auth store timeout", http.StatusServiceUnavailable)
				return
			}
			http.Error(w, "invalid api key", http.StatusUnauthorized)
			return
		}

		mac := hmac.New(sha256.New, serverPepper)
		mac.Write([]byte(keyID))
		mac.Write([]byte(":"))
		mac.Write([]byte(rawSecret))
		expected := mac.Sum(nil)

		if rec == nil || rec.Disabled || !hmac.Equal(rec.SecretMAC, expected) {
			http.Error(w, "invalid api key", http.StatusUnauthorized)
			return
		}

		ctx := context.WithValue(r.Context(), accountCtxKey{}, rec.AccountID)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
