def parse_pe_import_directory_rva(buf: bytes) -> PeImportHeaderInfo:
    if len(buf) < 0x40 or buf[:2] != b"MZ":
        raise PeHeaderError("missing DOS MZ header")

    (lfanew,) = struct.unpack_from("<I", buf, 0x3C)
    if lfanew + 24 > len(buf) or buf[lfanew : lfanew + 4] != b"PE\x00\x00":
        raise PeHeaderError("invalid e_lfanew or missing PE signature")

    coff_off = lfanew + 4
    _machine, num_sections, _ts, _sym_ptr, _nsym, opt_size, _chars = struct.unpack_from(
        "<HHIIIHH", buf, coff_off
