        raise PeHeaderError("truncated PE OptionalHeader")

    (magic,) = struct.unpack_from("<H", buf, opt_off)
    if magic == 0x20B:
        is_plus = True
        rva_count_rel = 108
        dd_rel = 112
    elif magic == 0x10B:
        is_plus = False
        rva_count_rel = 92
        dd_rel = 96
    else:
        raise PeHeaderError(f"unsupported OptionalHeader magic: {magic:#x}")

    if opt_size < dd_rel:
        raise PeHeaderError("OptionalHeader shorter than DataDirectory offset")

    (num_dirs,) = struct.unpack_from("<I", buf, opt_off + rva_count_rel)
    if num_dirs < 2 or opt_size < dd_rel + 16:
