```ts
export function createJwtKeyRingAuth(
  keyRing: ReadonlyMap<string, Buffer>,
  nowSecFn = () => Math.floor(Date.now() / 1000),
): RequestHandler {
  return (req: Request, res: Response, next: NextFunction): void => {
    const auth = req.headers.authorization;
    if (!auth || !auth.startsWith("Bearer ")) {
      res.status(401).json({ error: "missing_bearer_token" });
      return;
    }

    const parts = auth.slice(7).trim().split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "malformed_jwt" });
      return;
    }

    let hdr: { alg?: unknown; kid?: unknown };
    try {
      hdr = JSON.parse(Buffer.from(parts[0], "base64url").toString("utf8"));
    } catch {
      res.status(401).json({ error: "invalid_jwt_header" });
      return;
    }

    if (hdr.alg !== "HS256" || typeof hdr.kid !== "string" || !hdr.kid) {
      res.status(401).json({ error: "unsupported_alg_or_missing_kid" });
      return;
    }

    const secret = keyRing.get(hdr.kid);
    if (!secret || secret.length < 32) {
      res.status(401).json({ error: "unknown_kid" });
      return;
    }

    const gotSig = Buffer.from(parts[2], "base64url");
    const expectedSig = createHmac("sha256", secret)
      .update(`${parts[0]}.${parts[1]}`, "ascii")
      .digest();

    if (gotSig.length !== expectedSig.length || !timingSafeEqual(gotSig, expectedSig)) {
      res.status(401).json({ error: "invalid_jwt_signature" });
      return;
    }

    let claims: { sub?: unknown; exp?: unknown };
    try {
      claims = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8"));
    } catch {
      res.status(401).json({ error: "invalid_jwt_claims" });
      return;
    }

    if (typeof claims.sub !== "string" || !claims.sub || typeof claims.exp !== "number" || claims.exp <= nowSecFn()) {
      res.status(401).json({ error: "expired_or_invalid_claims" });
      return;
    }

    req.jwtSubject = claims.sub;
    next();
  };
}
```

