            size_t needed = req_len - copied;
            size_t chunk = (avail_in_span < needed) ? avail_in_span : needed;
            memcpy(dst + copied, spans[i].ptr + in_span_off, chunk);
            copied += chunk;
            if (copied == req_len) {
                return true;
            }
        }
        stream_pos = span_end;
    }

