pub fn decode_msgpack_ext(buf: &[u8]) -> Result<(i8, &[u8], &[u8]), MsgpackExtError> {
    let &tag = buf.first().ok_or(MsgpackExtError::UnexpectedEof)?;
    let (type_idx, data_len): (usize, usize) = match tag {
        0xd4 => (1, 1),
        0xd5 => (1, 2),
        0xd6 => (1, 4),
        0xd7 => (1, 8),
        0xd8 => (1, 16),
        0xc7 => {
            let &n = buf.get(1).ok_or(MsgpackExtError::UnexpectedEof)?;
            (2, n as usize)
        }
        0xc8 => {
            let len_bytes = buf.get(1..3).ok_or(MsgpackExtError::UnexpectedEof)?;
            (3, u16::from_be_bytes([len_bytes[0], len_bytes[1]]) as usize)
        }
        other => return Err(MsgpackExtError::NotAnExtTag(other)),
    };

    let &raw_type = buf.get(type_idx).ok_or(MsgpackExtError::UnexpectedEof)?;
    let data_start = type_idx.checked_add(1).ok_or(MsgpackExtError::UnexpectedEof)?;
    let data_end = data_start
        .checked_add(data_len)
        .ok_or(MsgpackExtError::UnexpectedEof)?;

    let data = buf.get(data_start..data_end).ok_or(MsgpackExtError::UnexpectedEof)?;
    let rest = buf.get(data_end..).unwrap_or(&[]);
    Ok((raw_type as i8, data, rest))
}
