```go
func SignedRangeHandler(secret []byte, maxChunk int64, reader RangeReader) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		blobID := strings.TrimSpace(r.URL.Query().Get("blob_id"))
		rangeHdr := strings.TrimSpace(r.Header.Get("Range"))
		sigHex := strings.TrimSpace(r.Header.Get("X-Chunk-HMAC"))
		if blobID == "" || !strings.HasPrefix(rangeHdr, "bytes=") || strings.Contains(rangeHdr, ",") || sigHex == "" {
			http.Error(w, "missing or invalid range headers", http.StatusBadRequest)
			return
		}

		bounds := strings.SplitN(strings.TrimPrefix(rangeHdr, "bytes="), "-", 2)
		if len(bounds) != 2 {
			http.Error(w, "malformed byte range", http.StatusRequestedRangeNotSatisfiable)
			return
		}
		start, err1 := strconv.ParseInt(bounds[0], 10, 64)
		end, err2 := strconv.ParseInt(bounds[1], 10, 64)
		if err1 != nil || err2 != nil || start < 0 || end < start {
			http.Error(w, "invalid range bounds", http.StatusRequestedRangeNotSatisfiable)
			return
		}
		length := end - start + 1
		if length > maxChunk {
			http.Error(w, "range exceeds maximum chunk size", http.StatusRequestedRangeNotSatisfiable)
			return
		}

		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "invalid chunk mac", http.StatusForbidden)
			return
		}
		mac := hmac.New(sha256.New, secret)
		_, _ = fmt.Fprintf(mac, "%s:%d:%d", blobID, start, end)
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "chunk mac mismatch", http.StatusForbidden)
			return
		}

		chunk, totalSize, err := reader.ReadRange(r.Context(), blobID, start, length)
		if err != nil {
			http.Error(w, "range read failed", http.StatusBadGateway)
			return
		}

		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, start+int64(len(chunk))-1, totalSize))
		w.WriteHeader(http.StatusPartialContent)
		_, _ = w.Write(chunk)
	}
}
