func VerifyQuorum(
	trustedKeys map[string]ed25519.PublicKey,
	threshold int,
	artifactDigest []byte,
	sigs []Attestation,
) error {
	if threshold <= 0 || len(artifactDigest) != 32 || len(trustedKeys) < threshold {
		return ErrQuorumNotMet
	}

	msg := make([]byte, len(quorumDomain)+len(artifactDigest))
	copy(msg, quorumDomain)
	copy(msg[len(quorumDomain):], artifactDigest)

	seenKeyIDs := make(map[string]struct{}, len(sigs))
	valid := 0

	for _, att := range sigs {
		if _, dup := seenKeyIDs[att.KeyID]; dup {
			continue
		}
		pub, trusted := trustedKeys[att.KeyID]
		if !trusted || len(pub) != ed25519.PublicKeySize || len(att.Sig) != ed25519.SignatureSize {
			continue
		}
		if ed25519.Verify(pub, msg, att.Sig) {
			seenKeyIDs[att.KeyID] = struct{}{}
			valid++
			if valid >= threshold {
				return nil
			}
		}
	}

	return ErrQuorumNotMet
}
