pub fn collect_desc_slices<'a>(
    guest_mem: &'a [u8],
    desc_table: &[VirtqDesc],
    head_idx: u16,
) -> Result<Vec<&'a [u8]>, VirtqError> {
    if desc_table.is_empty() {
        return Err(VirtqError::DescriptorIndexOutOfBounds(head_idx));
    }

    let max_hops = desc_table.len();
    let mut cur_idx = head_idx;
    let mut hops = 0usize;
    let mut slices = Vec::new();

    loop {
        let desc = desc_table
            .get(cur_idx as usize)
            .ok_or(VirtqError::DescriptorIndexOutOfBounds(cur_idx))?;

        hops += 1;
        if hops > max_hops {
            return Err(VirtqError::DescriptorCycle);
        }

        let start = usize::try_from(desc.addr).map_err(|_| VirtqError::GuestMemoryOutOfBounds)?;
        let end = start
            .checked_add(desc.len as usize)
            .ok_or(VirtqError::GuestMemoryOutOfBounds)?;
        let slice = guest_mem
            .get(start..end)
            .ok_or(VirtqError::GuestMemoryOutOfBounds)?;
        slices.push(slice);

        if (desc.flags & VIRTQ_DESC_F_NEXT) == 0 {
            return Ok(slices);
        }
        cur_idx = desc.next;
    }
}
