func OIDCCallbackHandler(cookieSecret []byte, nowFn func() time.Time, exchangeFn CodeExchanger) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query()
		code := q.Get("code")
		queryState := q.Get("state")
		cookie, err := r.Cookie("__Host-oidc_state")

		http.SetCookie(w, &http.Cookie{
			Name:     "__Host-oidc_state",
			Value:    "",
			Path:     "/",
			MaxAge:   -1,
			HttpOnly: true,
			Secure:   true,
			SameSite: http.SameSiteLaxMode,
		})

		if err != nil || code == "" || queryState == "" {
			http.Error(w, "missing oidc callback state or code", http.StatusBadRequest)
			return
		}

		dotIdx := strings.LastIndexByte(cookie.Value, '.')
		if dotIdx <= 0 {
			http.Error(w, "malformed oidc state cookie", http.StatusForbidden)
			return
		}
		rawPayload, sigHex := cookie.Value[:dotIdx], cookie.Value[dotIdx+1:]
		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "invalid state signature", http.StatusForbidden)
			return
		}

		mac := hmac.New(sha256.New, cookieSecret)
		mac.Write([]byte(rawPayload))
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "state signature mismatch", http.StatusForbidden)
			return
		}

		fields := strings.Split(rawPayload, "|")
		if len(fields) != 3 {
			http.Error(w, "corrupt state payload", http.StatusForbidden)
			return
		}
		cookieState, verifier, expStr := fields[0], fields[1], fields[2]
		expUnix, err := strconv.ParseInt(expStr, 10, 64)
		if err != nil || nowFn().Unix() > expUnix {
			http.Error(w, "oidc state expired", http.StatusForbidden)
			return
		}
		if !hmac.Equal([]byte(cookieState), []byte(queryState)) {
			http.Error(w, "oidc csrf state mismatch", http.StatusForbidden)
			return
		}

		sessTok, err := exchangeFn(r.Context(), code, verifier)
		if err != nil {
			http.Error(w, "token exchange failed", http.StatusBadGateway)
			return
		}

		http.SetCookie(w, &http.Cookie{
			Name:     "__Host-session",
			Value:    sessTok,
			Path:     "/",
			HttpOnly: true,
			Secure:   true,
			SameSite: http.SameSiteStrictMode,
		})
		w.WriteHeader(http.StatusNoContent)
	}
}
