```ts
export function gcraRateLimiter(cfg: GcraConfig): MiddlewareHandler {
  if (cfg.rate <= 0 || cfg.periodMs <= 0 || cfg.burst < 1) {
    throw new RangeError("invalid GCRA rate/periodMs/burst configuration");
  }
  const emissionIntervalMs = cfg.periodMs / cfg.rate;
  const burstToleranceMs = emissionIntervalMs * (cfg.burst - 1);
  const nowOf = cfg.nowMsFn ?? (() => Date.now());
  const tatByKey = new Map<string, number>();

  return async (c, next) => {
    const key = cfg.keyFn(c);
    const nowMs = nowOf();
    const prevTat = tatByKey.get(key) ?? nowMs;
    const nextTat = Math.max(prevTat, nowMs) + emissionIntervalMs;
    const allowAtMs = nextTat - burstToleranceMs;

    if (allowAtMs > nowMs) {
      const retryAfterSec = Math.max(1, Math.ceil((allowAtMs - nowMs) / 1000));
      c.header("Retry-After", String(retryAfterSec));
      c.header("RateLimit-Remaining", "0");
      return c.json({ error: "gcra_rate_limit_exceeded", retry_after_seconds: retryAfterSec }, 429);
    }

    tatByKey.set(key, nextTat);
    const remainingCapacityMs = Math.max(0, burstToleranceMs - (nextTat - nowMs));
    const remainingTokens = Math.floor(remainingCapacityMs / emissionIntervalMs);
    c.header("RateLimit-Remaining", String(remainingTokens));
    await next();
  };
}
