```ts
const B64U_RE = /^[A-Za-z0-9_-]+$/;

export function signCompactEdDsa(privKey: KeyObject, payload: Buffer, kid?: string): string {
  if (privKey.type !== "private" || privKey.asymmetricKeyType !== "ed25519") {
    throw new Error("signCompactEdDsa requires an Ed25519 private KeyObject");
  }
  const hdrObj: Record<string, string> = { alg: "EdDSA", typ: "JWT" };
  if (kid) hdrObj.kid = kid;

  const hdrB64 = Buffer.from(JSON.stringify(hdrObj), "utf8").toString("base64url");
  const payB64 = payload.toString("base64url");
  const signingInput = Buffer.from(`${hdrB64}.${payB64}`, "ascii");
  const sigB64 = sign(null, signingInput, privKey).toString("base64url");
  return `${hdrB64}.${payB64}.${sigB64}`;
}

export function verifyCompactEdDsa(pubKey: KeyObject, jws: string): Buffer {
  if (pubKey.type !== "public" || pubKey.asymmetricKeyType !== "ed25519") {
    throw new Error("verifyCompactEdDsa requires an Ed25519 public KeyObject");
  }
  const parts = jws.split(".");
  if (parts.length !== 3 || !B64U_RE.test(parts[0]) || !B64U_RE.test(parts[2])) {
    throw new Error("malformed compact JWS");
  }
  if (parts[1].length > 0 && !B64U_RE.test(parts[1])) {
    throw new Error("invalid base64url JWS payload");
  }

  let hdr: { alg?: unknown; crit?: unknown };
  try {
    hdr = JSON.parse(Buffer.from(parts[0], "base64url").toString("utf8"));
  } catch {
    throw new Error("invalid JWS JSON header");
  }
  if (hdr.alg !== "EdDSA" || hdr.crit !== undefined) {
    throw new Error("unsupported JWS alg or unhandled crit header");
  }

  const sigBuf = Buffer.from(parts[2], "base64url");
  if (sigBuf.length !== 64) {
    throw new Error("invalid Ed25519 signature byte length");
  }

  const signingInput = Buffer.from(`${parts[0]}.${parts[1]}`, "ascii");
  if (!verify(null, signingInput, pubKey, sigBuf)) {
    throw new Error("EdDSA JWS signature verification failed");
  }
  return Buffer.from(parts[1], "base64url");
}
```

