pub fn parse_riff_wave_chunks(buf: &[u8]) -> Result<Vec<RiffSubchunk<'_>>, RiffError> {
    let hdr = buf.get(..12).ok_or(RiffError::InvalidRiffHeader)?;
    if &hdr[0..4] != b"RIFF" || &hdr[8..12] != b"WAVE" {
        return Err(RiffError::InvalidRiffHeader);
    }

    let riff_size = u32::from_le_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]) as usize;
    if riff_size < 4 {
        return Err(RiffError::InvalidRiffHeader);
    }
    let riff_end = 8usize.checked_add(riff_size).ok_or(RiffError::Overflow)?;
    let wave_body = buf.get(12..riff_end).ok_or(RiffError::TruncatedChunk)?;

    let mut pos = 0usize;
    let mut out = Vec::new();
    while pos < wave_body.len() {
        let chdr_end = pos.checked_add(8).ok_or(RiffError::Overflow)?;
        let chdr = wave_body.get(pos..chdr_end).ok_or(RiffError::TruncatedChunk)?;
        let id = [chdr[0], chdr[1], chdr[2], chdr[3]];
        let sz = u32::from_le_bytes([chdr[4], chdr[5], chdr[6], chdr[7]]) as usize;

        let data_end = chdr_end.checked_add(sz).ok_or(RiffError::Overflow)?;
        let data = wave_body.get(chdr_end..data_end).ok_or(RiffError::TruncatedChunk)?;
        out.push(RiffSubchunk { id, data });

        let padded_sz = sz.checked_add(sz & 1).ok_or(RiffError::Overflow)?;
        let next_pos = chdr_end.checked_add(padded_sz).ok_or(RiffError::Overflow)?;
        if next_pos > wave_body.len() {
            return Err(RiffError::TruncatedChunk);
        }
        pos = next_pos;
    }
    Ok(out)
}
```

