```ts
const MAX_SKEW_SEC = 300;
const HEX64_RE = /^[0-9a-fA-F]{64}$/;

export function webhookReplayNonceGuard(
  secretsByKeyId: ReadonlyMap<string, Buffer>,
  nowSecFn = () => Math.floor(Date.now() / 1000),
): RequestHandler {
  const seenNonces = new Map<string, number>();

  return (req: Request, res: Response, next: NextFunction): void => {
    const keyId = req.header("x-key-id")?.trim();
    const tsRaw = req.header("x-timestamp")?.trim();
    const nonce = req.header("x-nonce")?.trim();
    const sigHex = req.header("x-signature")?.trim();

    if (!keyId || !tsRaw || !nonce || !sigHex || nonce.length < 16 || nonce.length > 128 || !HEX64_RE.test(sigHex)) {
      res.status(401).json({ error: "invalid_webhook_headers" });
      return;
    }
    if (!Buffer.isBuffer(req.rawBody)) {
      res.status(400).json({ error: "missing_raw_body" });
      return;
    }

    const secret = secretsByKeyId.get(keyId);
    if (!secret) {
      res.status(401).json({ error: "unknown_key_id" });
      return;
    }

    const tsSec = Number(tsRaw);
    const nowSec = nowSecFn();
    if (!Number.isSafeInteger(tsSec) || Math.abs(nowSec - tsSec) > MAX_SKEW_SEC) {
      res.status(401).json({ error: "timestamp_out_of_bounds" });
      return;
    }

    for (const [k, exp] of seenNonces) {
      if (exp <= nowSec) seenNonces.delete(k);
    }

    const replayKey = `${keyId}:${nonce}`;
    if (seenNonces.has(replayKey)) {
      res.status(409).json({ error: "replayed_webhook_nonce" });
      return;
    }

    const expectedMac = createHmac("sha256", secret)
      .update(`${keyId}.${tsRaw}.${nonce}.`, "utf8")
      .update(req.rawBody)
      .digest();
    const providedMac = Buffer.from(sigHex, "hex");

    if (providedMac.length !== expectedMac.length || !timingSafeEqual(providedMac, expectedMac)) {
      res.status(401).json({ error: "signature_mismatch" });
      return;
    }

    seenNonces.set(replayKey, nowSec + MAX_SKEW_SEC * 2);
    next();
  };
}
```

