    if ((b0 >> 4) != 3u) {
        return false;
    }
    uint8_t qos = (b0 >> 1) & 0x03u;
    if (qos == 3u) {
        return false;
    }

    size_t pos = 1u;
    size_t rem_len = 0u;
    unsigned shift = 0u;
    while (true) {
        if (pos >= buf_len || shift > 21u) {
            return false;
        }
        uint8_t enc = buf[pos++];
        rem_len |= ((size_t)(enc & 0x7Fu)) << shift;
        if ((enc & 0x80u) == 0u) {
            break;
        }
        shift += 7u;
    }

    size_t pkt_end = 0;
    if (ckd_add(&pkt_end, pos, rem_len) || pkt_end > buf_len) {
        return false;
    }

    size_t topic_hdr_end = 0;
    if (ckd_add(&topic_hdr_end, pos, (size_t)2u) || topic_hdr_end > pkt_end) {
        return false;
    }
    size_t topic_len = ((size_t)buf[pos] << 8) | (size_t)buf[pos + 1u];
    if (topic_len == 0u) {
        return false;
    }

    size_t topic_end = 0;
    if (ckd_add(&topic_end, topic_hdr_end, topic_len) || topic_end > pkt_end) {
        return false;
    }
    pos = topic_end;

    uint16_t pkt_id = 0u;
    if (qos > 0u) {
        size_t id_end = 0;
        if (ckd_add(&id_end, pos, (size_t)2u) || id_end > pkt_end) {
            return false;
        }
        pkt_id = ((uint16_t)buf[pos] << 8) | (uint16_t)buf[pos + 1u];
        if (pkt_id == 0u) {
            return false;
        }
        pos = id_end;
    }

    out->qos = qos;
    out->packet_id = pkt_id;
    out->topic = buf + topic_hdr_end;
    out->topic_len = topic_len;
    out->payload = buf + pos;
    out->payload_len = pkt_end - pos;
    return true;
}
