```rust
fn bundle_digest(manifest_json: &[u8], wasm_bytes: &[u8]) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"wasm-plugin-v1\x00");
    hasher.update((manifest_json.len() as u32).to_be_bytes());
    hasher.update(manifest_json);
    hasher.update((wasm_bytes.len() as u64).to_be_bytes());
    hasher.update(wasm_bytes);
    hasher.finalize().into()
}

pub fn sign_plugin_bundle(sk: &SigningKey, manifest_json: &[u8], wasm_bytes: &[u8]) -> [u8; 64] {
    let digest = bundle_digest(manifest_json, wasm_bytes);
    sk.sign(&digest).to_bytes()
}

pub fn verify_plugin_bundle(
    vk: &VerifyingKey,
    manifest_json: &[u8],
    wasm_bytes: &[u8],
    sig_bytes: &[u8; 64],
) -> Result<(), BundleSigError> {
    if vk.is_weak() {
        return Err(BundleSigError::InvalidSignature);
    }
    let digest = bundle_digest(manifest_json, wasm_bytes);
    let sig = Signature::from_bytes(sig_bytes);
    vk.verify_strict(&digest, &sig)
        .map_err(|_| BundleSigError::InvalidSignature)
}
