pub fn read_quic_varint(buf: &[u8], pos: &mut usize) -> Result<u64, QuicFrameError> {
    let &first = buf.get(*pos).ok_or(QuicFrameError::Truncated)?;
    let width = 1usize << (first >> 6);
    let end = pos.checked_add(width).ok_or(QuicFrameError::Truncated)?;
    let raw = buf.get(*pos..end).ok_or(QuicFrameError::Truncated)?;

    let mut val = (raw[0] & 0x3f) as u64;
    for &b in &raw[1..] {
        val = (val << 8) | (b as u64);
    }
    *pos = end;
    Ok(val)
}

pub fn parse_crypto_frame(buf: &[u8], start: usize) -> Result<QuicCryptoFrame<'_>, QuicFrameError> {
    let &ftype = buf.get(start).ok_or(QuicFrameError::Truncated)?;
    if ftype != 0x06 {
        return Err(QuicFrameError::NotCryptoFrame(ftype));
    }

    let mut pos = start.checked_add(1).ok_or(QuicFrameError::Truncated)?;
    let stream_offset = read_quic_varint(buf, &mut pos)?;
    let length = read_quic_varint(buf, &mut pos)?;

    let stream_end = stream_offset
        .checked_add(length)
        .ok_or(QuicFrameError::OffsetBoundsExceeded)?;
    if stream_end > QUIC_MAX_VARINT {
        return Err(QuicFrameError::OffsetBoundsExceeded);
    }

    let len_usize = usize::try_from(length).map_err(|_| QuicFrameError::OffsetBoundsExceeded)?;
    let next_pos = pos.checked_add(len_usize).ok_or(QuicFrameError::Truncated)?;
    let data = buf.get(pos..next_pos).ok_or(QuicFrameError::Truncated)?;

    Ok(QuicCryptoFrame {
        stream_offset,
        data,
        next_pos,
    })
}
