```go
func AuthenticatedRPCBridge(sharedSecret []byte, nowFn func() time.Time, callRPC RPCInvoker) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tsStr := strings.TrimSpace(r.Header.Get("X-Svc-Timestamp"))
		sigHex := strings.TrimSpace(r.Header.Get("X-Svc-HMAC"))
		if tsStr == "" || sigHex == "" {
			http.Error(w, "missing service auth headers", http.StatusUnauthorized)
			return
		}

		tsUnix, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil {
			http.Error(w, "invalid service timestamp", http.StatusBadRequest)
			return
		}
		skew := nowFn().Sub(time.Unix(tsUnix, 0))
		if skew < -60*time.Second || skew > 60*time.Second {
			http.Error(w, "service timestamp out of window", http.StatusUnauthorized)
			return
		}

		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "malformed service mac", http.StatusUnauthorized)
			return
		}

		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 1<<20))
		if err != nil {
			http.Error(w, "invalid rpc body", http.StatusBadRequest)
			return
		}

		bodySum := sha256.Sum256(body)
		mac := hmac.New(sha256.New, sharedSecret)
		mac.Write([]byte(r.Method + "\n" + r.URL.Path + "\n" + tsStr + "\n" + hex.EncodeToString(bodySum[:])))
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "service signature mismatch", http.StatusUnauthorized)
			return
		}

		rpcCtx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
		defer cancel()

		respBytes, err := callRPC(rpcCtx, r.URL.Path, body)
		if err != nil {
			if errors.Is(r.Context().Err(), context.Canceled) {
				w.WriteHeader(499)
				return
			}
			if errors.Is(err, context.DeadlineExceeded) {
				http.Error(w, "rpc deadline exceeded", http.StatusGatewayTimeout)
				return
			}
			http.Error(w, "rpc invocation failed", http.StatusBadGateway)
			return
		}

		w.Header().Set("Content-Type", "application/octet-stream")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(respBytes)
	}
}
