```python
def verify_png_chunks(buf: bytes) -> tuple[int, int, list[str]]:
    if len(buf) < 8 or buf[:8] != PNG_SIG:
        raise PngIntegrityError("invalid 8-byte PNG signature")

    pos = 8
    total = len(buf)
    chunk_types: list[str] = []
    width = 0
    height = 0
    saw_iend = False

    while pos < total:
        if saw_iend:
            raise PngIntegrityError("trailing bytes after IEND chunk")
        if pos + 12 > total:
            raise PngIntegrityError("truncated PNG chunk header/CRC")

        (length,) = struct.unpack_from(">I", buf, pos)
        ctype = buf[pos + 4 : pos + 8]
        if not all((65 <= b <= 90) or (97 <= b <= 122) for b in ctype):
            raise PngIntegrityError("non-alphabetic PNG chunk type")

        data_start = pos + 8
        data_end = data_start + length
        if data_end + 4 > total:
            raise PngIntegrityError("truncated PNG chunk data")

        data = buf[data_start:data_end]
        (expected_crc,) = struct.unpack_from(">I", buf, data_end)
        actual_crc = zlib.crc32(buf[pos + 4 : data_end]) & 0xFFFFFFFF
        if actual_crc != expected_crc:
            raise PngIntegrityError(f"CRC32 mismatch in {ctype.decode('ascii')} chunk")

        type_str = ctype.decode("ascii")
        if not chunk_types:
            if type_str != "IHDR" or length != 13:
                raise PngIntegrityError("first chunk must be 13-byte IHDR")
            width, height = struct.unpack_from(">II", data, 0)
            if width == 0 or height == 0:
                raise PngIntegrityError("zero dimension in IHDR")
        elif type_str == "IHDR":
            raise PngIntegrityError("duplicate IHDR chunk")

        if type_str == "IEND":
            if length != 0:
                raise PngIntegrityError("IEND chunk must have zero length")
            saw_iend = True

        chunk_types.append(type_str)
        pos = data_end + 4

    if not saw_iend:
        raise PngIntegrityError("missing IEND chunk")
    return width, height, chunk_types
```

