pub fn parse_der_sequence(input: &[u8]) -> Result<(&[u8], &[u8]), DerError> {
    let &tag = input.first().ok_or(DerError::Truncated)?;
    if tag != 0x30 {
        return Err(DerError::WrongTag(tag));
