    let &len_b0 = input.get(1).ok_or(DerError::Truncated)?;

    let (hdr_end, content_len): (usize, usize) = if (len_b0 & 0x80) == 0 {
        (2, len_b0 as usize)
    } else {
        let num_octets = (len_b0 & 0x7f) as usize;
        if num_octets == 0 || len_b0 == 0xff {
            return Err(DerError::IndefiniteOrReservedLength);
        }
        if num_octets > 4 {
            return Err(DerError::LengthOverflow);
        }
        let end = 2usize.checked_add(num_octets).ok_or(DerError::LengthOverflow)?;
        let octets = input.get(2..end).ok_or(DerError::Truncated)?;
        if octets[0] == 0 {
            return Err(DerError::NonMinimalLength);
        }
        let mut val = 0usize;
        for &b in octets {
            val = (val << 8) | (b as usize);
        }
        if val < 128 {
            return Err(DerError::NonMinimalLength);
        }
        (end, val)
    };

    let seq_end = hdr_end.checked_add(content_len).ok_or(DerError::LengthOverflow)?;
    let content = input.get(hdr_end..seq_end).ok_or(DerError::Truncated)?;
    let rest = input.get(seq_end..).unwrap_or(&[]);
    Ok((content, rest))
