            pos += 1
            chars: list[str] = []
            closed = False
            while pos < n:
                ch = line[pos]
                if ch == "\\":
                    pos += 1
                    if pos >= n:
                        raise ValueError("unterminated escape in logfmt value")
                    esc = line[pos]
                    chars.append(_ESCAPES.get(esc, esc))
                    pos += 1
                elif ch == '"':
                    closed = True
                    pos += 1
                    break
                else:
                    chars.append(ch)
                    pos += 1
            if not closed or (pos < n and not line[pos].isspace()):
                raise ValueError("malformed quoted logfmt value")
            out[key] = "".join(chars)
        else:
