func (c *CounterGCM) buildAAD(nonce []byte, callerAAD []byte) []byte {
	out := make([]byte, 12+len(callerAAD))
	copy(out[:12], nonce)
	copy(out[12:], callerAAD)
	return out
}

func (c *CounterGCM) Seal(aad, plaintext []byte) ([]byte, error) {
	c.mu.Lock()
	if c.seq == math.MaxUint64 {
		c.mu.Unlock()
		return nil, ErrNonceExhausted
	}
	curSeq := c.seq
	c.seq++
	c.mu.Unlock()

	var nonce [12]byte
	copy(nonce[0:4], c.prefix[:])
	binary.BigEndian.PutUint64(nonce[4:12], curSeq)

	dst := make([]byte, 12, 12+len(plaintext)+c.gcm.Overhead())
	copy(dst, nonce[:])
	return c.gcm.Seal(dst, nonce[:], plaintext, c.buildAAD(nonce[:], aad)), nil
}

func (c *CounterGCM) Open(aad, packet []byte) ([]byte, error) {
	if len(packet) < 12+c.gcm.Overhead() {
		return nil, ErrOpenFailed
	}
	nonce := packet[:12]
	ct := packet[12:]
	pt, err := c.gcm.Open(nil, nonce, ct, c.buildAAD(nonce, aad))
	if err != nil {
		return nil, ErrOpenFailed
	}
	return pt, nil
