```rust
pub fn parse_socks5_target(buf: &[u8], offset: usize) -> Result<(Socks5Target<'_>, usize), Socks5ParseError> {
    let &atyp = buf.get(offset).ok_or(Socks5ParseError::Truncated)?;
    let mut pos = offset.checked_add(1).ok_or(Socks5ParseError::Truncated)?;

    let host = match atyp {
        0x01 => {
            let end = pos.checked_add(4).ok_or(Socks5ParseError::Truncated)?;
            let s = buf.get(pos..end).ok_or(Socks5ParseError::Truncated)?;
            pos = end;
            Socks5Host::Ipv4([s[0], s[1], s[2], s[3]])
        }
        0x03 => {
            let &dlen = buf.get(pos).ok_or(Socks5ParseError::Truncated)?;
            if dlen == 0 {
                return Err(Socks5ParseError::InvalidDomain);
            }
            let start = pos.checked_add(1).ok_or(Socks5ParseError::Truncated)?;
            let end = start.checked_add(dlen as usize).ok_or(Socks5ParseError::Truncated)?;
            let raw_dom = buf.get(start..end).ok_or(Socks5ParseError::Truncated)?;
            if !raw_dom.iter().all(|b| b.is_ascii_alphanumeric() || *b == b'.' || *b == b'-') {
                return Err(Socks5ParseError::InvalidDomain);
            }
            let dom_str = core::str::from_utf8(raw_dom).map_err(|_| Socks5ParseError::InvalidDomain)?;
            pos = end;
            Socks5Host::Domain(dom_str)
        }
        0x04 => {
            let end = pos.checked_add(16).ok_or(Socks5ParseError::Truncated)?;
            let s = buf.get(pos..end).ok_or(Socks5ParseError::Truncated)?;
            let mut ip6 = [0u8; 16];
            ip6.copy_from_slice(s);
            pos = end;
            Socks5Host::Ipv6(ip6)
        }
        other => return Err(Socks5ParseError::UnsupportedAtyp(other)),
    };

    let port_end = pos.checked_add(2).ok_or(Socks5ParseError::Truncated)?;
    let pbytes = buf.get(pos..port_end).ok_or(Socks5ParseError::Truncated)?;
    let port = u16::from_be_bytes([pbytes[0], pbytes[1]]);

    Ok((Socks5Target { host, port }, port_end))
}
