```go
func RotateSessionHandler(secret []byte, ttl time.Duration, nowFn func() time.Time, store SessionStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		cookie, err := r.Cookie("__Host-sid")
		if err != nil || cookie.Value == "" {
			http.Error(w, "missing session cookie", http.StatusUnauthorized)
			return
		}

		dot := strings.LastIndexByte(cookie.Value, '.')
		if dot <= 0 {
			http.Error(w, "malformed session cookie", http.StatusUnauthorized)
			return
		}
		rawVal, sigHex := cookie.Value[:dot], cookie.Value[dot+1:]
		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "invalid session mac", http.StatusUnauthorized)
			return
		}

		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(rawVal))
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "session mac mismatch", http.StatusUnauthorized)
			return
		}

		parts := strings.Split(rawVal, "|")
		if len(parts) != 3 || parts[0] == "" || parts[1] == "" {
			http.Error(w, "corrupt session claims", http.StatusUnauthorized)
			return
		}
		oldSID, userID, expStr := parts[0], parts[1], parts[2]
		expUnix, err := strconv.ParseInt(expStr, 10, 64)
		now := nowFn()
		if err != nil || now.Unix() >= expUnix {
			http.Error(w, "session expired", http.StatusUnauthorized)
			return
		}

		var rnd [16]byte
		if _, err := rand.Read(rnd[:]); err != nil {
			http.Error(w, "entropy failure", http.StatusInternalServerError)
			return
		}
		newSID := hex.EncodeToString(rnd[:])
		newExp := now.Add(ttl)

		if err := store.Rotate(r.Context(), oldSID, newSID, userID, newExp); err != nil {
			http.Error(w, "session rotation rejected", http.StatusUnauthorized)
			return
		}

		newPayload := fmt.Sprintf("%s|%s|%d", newSID, userID, newExp.Unix())
		newMac := hmac.New(sha256.New, secret)
		newMac.Write([]byte(newPayload))
		signedVal := newPayload + "." + hex.EncodeToString(newMac.Sum(nil))

		http.SetCookie(w, &http.Cookie{
			Name:     "__Host-sid",
			Value:    signedVal,
			Path:     "/",
			MaxAge:   int(ttl.Seconds()),
			HttpOnly: true,
			Secure:   true,
			SameSite: http.SameSiteStrictMode,
		})
		w.WriteHeader(http.StatusNoContent)
	}
}
