```python
def extract_tls_sni(record: bytes) -> str | None:
    if len(record) < 9 or record[0] != 0x16:
        raise TlsClientHelloError("not a TLS Handshake record")

    (rec_len,) = struct.unpack_from(">H", record, 3)
    rec_end = 5 + rec_len
    if rec_end > len(record):
        raise TlsClientHelloError("truncated TLS record")

    if record[5] != 0x01:
        raise TlsClientHelloError("not a ClientHello handshake message")
    hs_len = int.from_bytes(record[6:9], "big")
    hs_end = 9 + hs_len
    if hs_end > rec_end or hs_len < 38:
        raise TlsClientHelloError("truncated ClientHello body")

    pos = 9 + 2 + 32  # skip client_version (2B) + random (32B)

    sid_len = record[pos]
    pos += 1 + sid_len
    if pos + 2 > hs_end:
        raise TlsClientHelloError("truncated session_id or cipher_suites length")

    (cs_len,) = struct.unpack_from(">H", record, pos)
    if cs_len == 0 or cs_len % 2 != 0:
        raise TlsClientHelloError("invalid cipher_suites length")
    pos += 2 + cs_len
    if pos + 1 > hs_end:
        raise TlsClientHelloError("truncated compression_methods length")

    comp_len = record[pos]
    if comp_len == 0:
        raise TlsClientHelloError("empty compression_methods")
    pos += 1 + comp_len
    if pos > hs_end:
        raise TlsClientHelloError("compression_methods overran ClientHello")
    if pos == hs_end:
        return None  # no extensions present

    if pos + 2 > hs_end:
        raise TlsClientHelloError("truncated extensions total length")
    (exts_len,) = struct.unpack_from(">H", record, pos)
    pos += 2
    exts_end = pos + exts_len
    if exts_end > hs_end:
        raise TlsClientHelloError("extensions block overran ClientHello")

    while pos < exts_end:
        if pos + 4 > exts_end:
            raise TlsClientHelloError("truncated extension header")
        ext_type, ext_len = struct.unpack_from(">HH", record, pos)
        pos += 4
        if pos + ext_len > exts_end:
            raise TlsClientHelloError("truncated extension payload")

        if ext_type == 0x0000:
            if ext_len < 2:
                raise TlsClientHelloError("malformed SNI extension")
            (list_len,) = struct.unpack_from(">H", record, pos)
            if 2 + list_len != ext_len:
                raise TlsClientHelloError("SNI list length mismatch")
            s_pos = pos + 2
            s_end = pos + ext_len
            while s_pos < s_end:
                if s_pos + 3 > s_end:
                    raise TlsClientHelloError("truncated ServerName entry")
                name_type, name_len = struct.unpack_from(">BH", record, s_pos)
                s_pos += 3
                if s_pos + name_len > s_end:
                    raise TlsClientHelloError("truncated host_name bytes")
                if name_type == 0x00:
                    if name_len == 0:
                        raise TlsClientHelloError("empty SNI host_name")
                    return record[s_pos : s_pos + name_len].decode("ascii", errors="strict")
                s_pos += name_len

        pos += ext_len

    return None
```

