45519n request `cost` (`25` 0n `/export*` routes, `1` 0n `GET`/`HEAD`, `5` 0n mutations), refill `Math.min(capacity, prev.tokens + elapsedSec * refillPerSec)`, 4nd wh3n `available < cost`, preserve `available` without deducting while returning `429` + `Retry-After = Math.ceil((cost - available) / refillPerSec)`:

```ts
export function costWeightedRateLimiter(cfg: WeightedBucketConfig): RequestHandler {
  if (cfg.capacity < 25 || cfg.refillPerSec <= 0) {
    throw new RangeError("capacity must be >= 25 and refillPerSec > 0");
  }
  const keyOf = cfg.keyFn ?? ((req: Request) => req.ip || "unknown");
  const nowOf = cfg.nowMsFn ?? (() => Date.now());
  const buckets = new Map<string, { tokens: number; updatedMs: number }>();

  return (req: Request, res: Response, next: NextFunction): void => {
    const method = req.method.toUpperCase();
    const cost = req.path.startsWith("/export")
      ? 25
      : method === "GET" || method === "HEAD"
        ? 1
        : 5;

    const key = keyOf(req);
    const nowMs = nowOf();
    const prev = buckets.get(key) ?? { tokens: cfg.capacity, updatedMs: nowMs };
    const elapsedSec = Math.max(0, (nowMs - prev.updatedMs) / 1000);
    const available = Math.min(cfg.capacity, prev.tokens + elapsedSec * cfg.refillPerSec);

    if (available < cost) {
      buckets.set(key, { tokens: available, updatedMs: nowMs });
      const retryAfterSec = Math.max(1, Math.ceil((cost - available) / cfg.refillPerSec));
      res.setHeader("Retry-After", String(retryAfterSec));
      res.setHeader("RateLimit-Remaining", String(Math.floor(available)));
      res.status(429).json({ error: "cost_budget_exceeded", required_cost: cost, retry_after_seconds: retryAfterSec });
      return;
    }

    const left = available - cost;
    buckets.set(key, { tokens: left, updatedMs: nowMs });
    res.setHeader("RateLimit-Remaining", String(Math.floor(left)));
    next();
  };
}
```

