```c
static inline bool bip_invariants_ok(const bip_buf_t *bb) {
    return bb != nullptr
        && bb->buf != nullptr
        && bb->cap > 0u
        && bb->b_end <= bb->a_start
        && bb->a_start <= bb->a_end
        && bb->a_end <= bb->cap;
}

[[nodiscard]] bool bip_peek_contiguous(const bip_buf_t *bb, const uint8_t **out_ptr, size_t *out_len) {
    if (!bip_invariants_ok(bb) || out_ptr == nullptr || out_len == nullptr) {
        return false;
    }
    size_t avail = bb->a_end - bb->a_start;
    *out_ptr = (avail > 0u) ? (bb->buf + bb->a_start) : bb->buf;
    *out_len = avail;
    return true;
}

[[nodiscard]] bool bip_commit_read(bip_buf_t *bb, size_t consume_len) {
    if (!bip_invariants_ok(bb)) {
        return false;
    }
    size_t avail = bb->a_end - bb->a_start;
    if (consume_len > avail) {
        return false;
    }

    size_t next_start = 0;
    if (ckd_add(&next_start, bb->a_start, consume_len)) {
        return false;
    }
    bb->a_start = next_start;

    if (bb->a_start == bb->a_end) {
        if (bb->b_end > 0u) {
            bb->a_start = 0u;
            bb->a_end = bb->b_end;
            bb->b_end = 0u;
        } else {
            bb->a_start = 0u;
            bb->a_end = 0u;
        }
    }
    return true;
}
