```ts
const HEADER_LEN = 6 + 32 + 12 + 16; // 66 bytes

function backupAad(backupId: string, createdAtSec: number): Buffer {
  const idBuf = Buffer.from(backupId, "utf8");
  const aad = Buffer.allocUnsafe(6 + 4 + idBuf.length + 8);
  MAGIC.copy(aad, 0);
  aad.writeUInt32BE(idBuf.length, 6);
  idBuf.copy(aad, 10);
  aad.writeBigInt64BE(BigInt(createdAtSec), 10 + idBuf.length);
  return aad;
}

export function sealBackup(
  rootKey: Buffer,
  backupId: string,
  createdAtSec: number,
  data: Buffer,
): Buffer {
  if (rootKey.length < 32) {
    throw new Error("rootKey must be at least 32 bytes");
  }
  const salt = randomBytes(32);
  const subkey = Buffer.from(hkdfSync("sha256", rootKey, salt, "backup-enc-v1", 32));
  const iv = randomBytes(12);

  const cipher = createCipheriv("aes-256-gcm", subkey, iv, { authTagLength: 16 });
  cipher.setAAD(backupAad(backupId, createdAtSec));
  const ct = Buffer.concat([cipher.update(data), cipher.final()]);
  const tag = cipher.getAuthTag();

  return Buffer.concat([MAGIC, salt, iv, tag, ct]);
}

export function openBackup(
  rootKey: Buffer,
  backupId: string,
  createdAtSec: number,
  archive: Buffer,
): Buffer {
  if (rootKey.length < 32 || archive.length < HEADER_LEN || !archive.subarray(0, 6).equals(MAGIC)) {
    throw new Error("invalid or truncated backup archive header");
  }
  const salt = archive.subarray(6, 38);
  const iv = archive.subarray(38, 50);
  const tag = archive.subarray(50, 66);
  const ct = archive.subarray(66);

  const subkey = Buffer.from(hkdfSync("sha256", rootKey, salt, "backup-enc-v1", 32));
  const decipher = createDecipheriv("aes-256-gcm", subkey, iv, { authTagLength: 16 });
  decipher.setAAD(backupAad(backupId, createdAtSec));
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ct), decipher.final()]);
}
```

