    pub opcode: u8,
    pub off: i16,
    pub imm: i32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VerifierError {
    EmptyProgram,
    MissingTerminalExit,
    JumpOutOfBounds { pc: usize, off: i16 },
}

pub fn verify_bpf_jumps(prog: &[BpfInsn]) -> Result<(), VerifierError> {
