    #[test]
    fn accepts_inbounds_jump_and_rejects_negative_escape() {
        let ok = [
            BpfInsn { opcode: 0x05, off: 1, imm: 0 }, // ja +1 -> lands on pc 2
            BpfInsn { opcode: 0xb7, off: 0, imm: 1 },
            BpfInsn { opcode: 0x95, off: 0, imm: 0 }, // exit
        ];
        assert_eq!(verify_bpf_jumps(&ok), Ok(()));

        let bad = [
            BpfInsn { opcode: 0x05, off: -2, imm: 0 }, // 0 + 1 + (-2) -> underflow!
            BpfInsn { opcode: 0x95, off: 0, imm: 0 },
