```rust
pub fn verify_bpf_jumps(prog: &[BpfInsn]) -> Result<(), VerifierError> {
    let last = prog.last().ok_or(VerifierError::EmptyProgram)?;
    if last.opcode != 0x95 || last.off != 0 {
        return Err(VerifierError::MissingTerminalExit);
    }

    for (pc, insn) in prog.iter().enumerate() {
        let class = insn.opcode & 0x07;
        if class == 0x05 && insn.opcode != 0x85 && insn.opcode != 0x95 {
            let next_pc = pc
                .checked_add(1)
                .and_then(|base| base.checked_add_signed(insn.off as isize))
                .ok_or(VerifierError::JumpOutOfBounds { pc, off: insn.off })?;
            if next_pc >= prog.len() {
                return Err(VerifierError::JumpOutOfBounds { pc, off: insn.off });
            }
        }
    }
    Ok(())
}
