_WS_STRIP_RE = re.compile(r"[\s]+")
_REQUIRED_TAGS = {"v", "a", "d", "s", "h", "bh", "b"}


def parse_dkim_signature(raw_value: str) -> DkimHeader:
    tags: dict[str, str] = {}
    parts = raw_value.split(";")
    for idx, part in enumerate(parts):
        cleaned = part.strip()
        if not cleaned:
            if idx == len(parts) - 1:
                continue
            raise DkimSyntaxError("empty tag-spec in DKIM-Signature")
        if "=" not in cleaned:
            raise DkimSyntaxError(f"missing '=' in DKIM tag: {cleaned!r}")
        k_raw, v_raw = cleaned.split("=", 1)
        key = k_raw.strip()
        if not _TAG_NAME_RE.match(key):
            raise DkimSyntaxError(f"invalid DKIM tag name: {key!r}")
        if key in tags:
            raise DkimSyntaxError(f"duplicate DKIM tag forbidden: {key}")
        tags[key] = v_raw.strip()

    missing = _REQUIRED_TAGS - tags.keys()
    if missing or tags["v"] != "1":
        raise DkimSyntaxError("missing required DKIM tags or unsupported v!=1")

    bh_clean = _WS_STRIP_RE.sub("", tags["bh"])
    b_clean = _WS_STRIP_RE.sub("", tags["b"])
    if not bh_clean or not b_clean:
        raise DkimSyntaxError("empty bh or b tag")

    try:
        body_hash = base64.b64decode(bh_clean, validate=True)
        sig_bytes = base64.b64decode(b_clean, validate=True)
    except Exception as exc:
        raise DkimSyntaxError("invalid base64 in bh or b tag") from exc

    signed_hdrs = [h.strip().lower() for h in tags["h"].split(":") if h.strip()]
    if not signed_hdrs or "from" not in signed_hdrs:
        raise DkimSyntaxError("DKIM h= tag must sign From header")

    return DkimHeader(
        algorithm=tags["a"].strip(),
        domain=tags["d"].strip().lower(),
        selector=tags["s"].strip(),
        signed_headers=signed_hdrs,
        body_hash=body_hash,
        signature=sig_bytes,
    )
