```ts
const HEX64_RE = /^[0-9a-fA-F]{64}$/;
const MAX_SKEW_SEC = 30;

export function createS2sHmacPreHandler(
  serviceSecrets: ReadonlyMap<string, Buffer>,
  allowedServices: ReadonlySet<string>,
  nowSecFn = () => Math.floor(Date.now() / 1000),
): preHandlerHookHandler {
  return async (req: FastifyRequest, reply: FastifyReply) => {
    const svcId = req.headers["x-svc-id"];
    const tsStr = req.headers["x-svc-ts"];
    const sigHex = req.headers["x-svc-sig"];

    if (typeof svcId !== "string" || typeof tsStr !== "string" || typeof sigHex !== "string" || !HEX64_RE.test(sigHex)) {
      return reply.code(401).send({ error: "missing_or_malformed_s2s_headers" });
    }

    const secret = serviceSecrets.get(svcId);
    if (!secret) {
      return reply.code(401).send({ error: "unknown_service_principal" });
    }

    const tsSec = Number(tsStr);
    if (!Number.isSafeInteger(tsSec) || Math.abs(nowSecFn() - tsSec) > MAX_SKEW_SEC) {
      return reply.code(401).send({ error: "s2s_timestamp_skew" });
    }

    const raw = Buffer.isBuffer(req.rawBody) ? req.rawBody : Buffer.alloc(0);
    const bodyHash = createHash("sha256").update(raw).digest("hex");
    const canonical = `${svcId}:${req.method.toUpperCase()}:${req.url}:${tsStr}:${bodyHash}`;

    const expectedMac = createHmac("sha256", secret).update(canonical, "utf8").digest();
    const providedMac = Buffer.from(sigHex, "hex");
    if (providedMac.length !== expectedMac.length || !timingSafeEqual(providedMac, expectedMac)) {
      return reply.code(401).send({ error: "s2s_signature_mismatch" });
    }

    if (!allowedServices.has(svcId)) {
      return reply.code(403).send({ error: "service_not_permitted_for_route" });
    }

    req.callerServiceId = svcId;
  };
}
```

