fn ipc_aad(hdr: &IpcHeader) -> [u8; 18] {
    let mut aad = [0u8; 18];
    aad[0..8].copy_from_slice(b"ipc-v1\x00\x00");
    aad[8..12].copy_from_slice(&hdr.sender_pid.to_be_bytes());
    aad[12..16].copy_from_slice(&hdr.receiver_pid.to_be_bytes());
    aad[16..18].copy_from_slice(&hdr.msg_type.to_be_bytes());
    aad
}

pub fn seal_ipc_msg(
    key: &[u8; 32],
    hdr: &IpcHeader,
    plaintext: &[u8],
) -> Result<Vec<u8>, IpcCryptoError> {
    let cipher = ChaCha20Poly1305::new(key.into());
    let nonce = ChaCha20Poly1305::generate_nonce(&mut OsRng);
    let aad = ipc_aad(hdr);
    let ct = cipher
        .encrypt(&nonce, Payload { msg: plaintext, aad: &aad })
        .map_err(|_| IpcCryptoError::AuthFailed)?;
    let mut out = Vec::with_capacity(12 + ct.len());
    out.extend_from_slice(nonce.as_slice());
    out.extend_from_slice(&ct);
    Ok(out)
}

pub fn open_ipc_msg(
    key: &[u8; 32],
    hdr: &IpcHeader,
    frame: &[u8],
) -> Result<Vec<u8>, IpcCryptoError> {
    if frame.len() < 12 + 16 {
        return Err(IpcCryptoError::Truncated);
    }
    let (nonce_bytes, ct) = frame.split_at(12);
    let cipher = ChaCha20Poly1305::new(key.into());
    let aad = ipc_aad(hdr);
    cipher
        .decrypt(Nonce::from_slice(nonce_bytes), Payload { msg: ct, aad: &aad })
        .map_err(|_| IpcCryptoError::AuthFailed)
}
