func RequireRoutingTicket(ticketKey []byte, localRegion string, nowFn func() time.Time, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hdrTenant := strings.TrimSpace(r.Header.Get("X-Tenant-ID"))
		ticket := strings.TrimSpace(r.Header.Get("X-Routing-Ticket"))
		if hdrTenant == "" || ticket == "" {
			http.Error(w, "missing tenant routing headers", http.StatusUnauthorized)
			return
		}

		dot := strings.LastIndexByte(ticket, '.')
		if dot <= 0 {
			http.Error(w, "malformed routing ticket", http.StatusUnauthorized)
			return
		}
		rawClaims, sigHex := ticket[:dot], ticket[dot+1:]
		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "invalid ticket mac", http.StatusUnauthorized)
			return
		}

		mac := hmac.New(sha256.New, ticketKey)
		mac.Write([]byte(rawClaims))
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "routing ticket signature mismatch", http.StatusUnauthorized)
			return
		}

		parts := strings.Split(rawClaims, "|")
		if len(parts) != 3 {
			http.Error(w, "corrupt ticket claims", http.StatusUnauthorized)
			return
		}
		ticketTenant, ticketRegion, expStr := parts[0], parts[1], parts[2]
		expUnix, err := strconv.ParseInt(expStr, 10, 64)
		if err != nil || nowFn().Unix() >= expUnix {
			http.Error(w, "routing ticket expired", http.StatusUnauthorized)
			return
		}
		if ticketTenant != hdrTenant || ticketRegion != localRegion {
			http.Error(w, "tenant or region scope mismatch", http.StatusForbidden)
			return
		}

		ctx := context.WithValue(r.Context(), scopeKey{}, TenantScope{
			TenantID: ticketTenant,
			Region:   ticketRegion,
		})
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}
