def sign_denylist(
    sk: Ed25519PrivateKey,
    seq_no: int,
    expires_unix: int,
    token_ids: list[bytes],
) -> bytes:
    unique_sorted = sorted(set(token_ids))
    for tid in unique_sorted:
        if len(tid) != 16:
            raise ValueError("each token_id must be 16 bytes")
    hdr = struct.pack(">QQI", seq_no, expires_unix, len(unique_sorted))
    body = hdr + b"".join(unique_sorted)
    sig = sk.sign(CRL_DOMAIN + body)
    return body + sig


def verify_denylist(
    pk: Ed25519PublicKey,
    bundle: bytes,
    last_accepted_seq: int,
    now_unix: int,
) -> tuple[int, set[bytes]]:
    if len(bundle) < 20 + 64:
        raise DenylistVerifyError("truncated denylist bundle")
    body = bundle[:-64]
    sig = bundle[-64:]

    try:
        pk.verify(sig, CRL_DOMAIN + body)
    except InvalidSignature as exc:
        raise DenylistVerifyError("invalid ed25519 denylist signature") from exc

    seq_no, expires_unix, count = struct.unpack_from(">QQI", body, 0)
    if seq_no <= last_accepted_seq:
        raise DenylistVerifyError(f"rollback detected: seq {seq_no} <= {last_accepted_seq}")
    if expires_unix <= now_unix:
        raise DenylistVerifyError("stale/frozen denylist expired")
    if 20 + count * 16 != len(body):
        raise DenylistVerifyError("corrupt token_id table length")

    revoked = {body[pos : pos + 16] for pos in range(20, len(body), 16)}
    return seq_no, revoked
