		if !exists {
			ent = &ipEntry{tokens: burst, lastSeen: now}
			buckets[ip] = ent
		} else {
			elapsed := now.Sub(ent.lastSeen).Seconds()
			if elapsed > 0 {
				ent.tokens = math.Min(burst, ent.tokens+elapsed*refillPerSec)
				ent.lastSeen = now
			}
		}

		if ent.tokens < 1.0 {
			retrySec := int(math.Ceil((1.0 - ent.tokens) / refillPerSec))
			if retrySec < 1 {
