export function createLoginBruteForceGuard(opts: LockoutOptions): RequestHandler {
  const tracker = new Map<string, { failures: number; lockedUntilMs: number }>();
  const nowOf = opts.nowMsFn ?? (() => Date.now());

  return (req: Request, res: Response, next: NextFunction): void => {
    const body = req.body as { email?: unknown } | undefined;
    const rawEmail = typeof body?.email === "string" ? body.email.trim().toLowerCase() : "";
