      res.setHeader("Retry-After", String(retrySec));
      res.status(429).json({ error: "account_temporarily_locked", retry_after_seconds: retrySec });
      return;
    }

    res.once("finish", () => {
      const finishNow = nowOf();
      if (res.statusCode >= 200 && res.statusCode < 300) {
        tracker.delete(bucketKey);
        return;
      }
      if (res.statusCode === 401) {
        const prev = tracker.get(bucketKey) ?? { failures: 0, lockedUntilMs: 0 };
