          const lockDuration = Math.min(opts.maxLockMs, opts.baseLockMs * (2 ** exp));
          lockedUntilMs = finishNow + lockDuration;
        }
        tracker.set(bucketKey, { failures, lockedUntilMs });
      }
    });

    next();
  };
}
