```python
def _parse_node(data: bytes, pos: int, depth: int, max_depth: int) -> tuple[Any, int]:
    if depth > max_depth:
        raise BencodeError("exceeded maximum bencode nesting depth")
    if pos >= len(data):
        raise BencodeError("unexpected EOF")

    tag = data[pos]
    if tag == ord("i"):
        end_idx = data.find(b"e", pos + 1)
        if end_idx == -1:
            raise BencodeError("unterminated bencode integer")
        raw_num = data[pos + 1 : end_idx]
        if not raw_num or raw_num == b"-0":
            raise BencodeError("empty or negative-zero bencode integer")
        if raw_num[0] == ord("-"):
            digits = raw_num[1:]
            if not digits or not digits.isdigit() or digits[0] == ord("0"):
                raise BencodeError("malformed negative bencode integer")
        else:
            if not raw_num.isdigit() or (len(raw_num) > 1 and raw_num[0] == ord("0")):
                raise BencodeError("leading zero or non-digit in bencode integer")
        return int(raw_num), end_idx + 1

    if tag == ord("l"):
        pos += 1
        items: list[Any] = []
        while pos < len(data) and data[pos] != ord("e"):
            val, pos = _parse_node(data, pos, depth + 1, max_depth)
            items.append(val)
        if pos >= len(data):
            raise BencodeError("unterminated bencode list")
        return items, pos + 1

    if tag == ord("d"):
        pos += 1
        out_dict: dict[bytes, Any] = {}
        prev_key: bytes | None = None
        while pos < len(data) and data[pos] != ord("e"):
            if not (48 <= data[pos] <= 57):
                raise BencodeError("bencode dictionary keys must be byte strings")
            key, pos = _parse_node(data, pos, depth + 1, max_depth)
            if prev_key is not None and key <= prev_key:
                raise BencodeError("unsorted or duplicate bencode dictionary key")
            prev_key = key
            val, pos = _parse_node(data, pos, depth + 1, max_depth)
            out_dict[key] = val
        if pos >= len(data):
            raise BencodeError("unterminated bencode dictionary")
        return out_dict, pos + 1

    if 48 <= tag <= 57:
        colon = data.find(b":", pos)
        if colon == -1:
            raise BencodeError("missing ':' in bencode byte string")
        len_raw = data[pos:colon]
        if not len_raw.isdigit() or (len(len_raw) > 1 and len_raw[0] == ord("0")):
            raise BencodeError("invalid or leading-zero byte string length")
        slen = int(len_raw)
        start = colon + 1
        end = start + slen
        if end > len(data):
            raise BencodeError("truncated bencode byte string")
        return data[start:end], end

    raise BencodeError(f"unexpected bencode byte: {tag:#x}")


def bdecode_strict(data: bytes, max_depth: int = 32) -> Any:
    val, end_pos = _parse_node(data, 0, 0, max_depth)
    if end_pos != len(data):
        raise BencodeError("trailing garbage after bencode root element")
    return val
