```ts
export function requireEntitlementAndQuota(
  quotaStore: QuotaStore,
  featureKey: string,
  units = 1,
): preHandlerHookHandler {
  if (!Number.isInteger(units) || units < 1) {
    throw new RangeError("units must be an integer >= 1");
  }

  return async (req: FastifyRequest, reply: FastifyReply) => {
    const plan = req.orgPlan;
    if (!plan || !plan.orgId) {
      return reply.code(401).send({ error: "missing_org_plan_context" });
    }

    if (!plan.features.includes(featureKey)) {
      return reply.code(403).send({ error: "feature_not_in_plan", feature: featureKey });
    }

    const limit = Object.prototype.hasOwnProperty.call(plan.monthlyLimits, featureKey)
      ? plan.monthlyLimits[featureKey]
      : 0;
    if (limit < units) {
      return reply.code(403).send({ error: "feature_quota_zero_or_insufficient_limit", feature: featureKey });
    }

    const res = await quotaStore.tryConsume(plan.orgId, featureKey, units, limit);
    reply.header("X-Quota-Remaining", String(Math.max(0, res.remaining)));

    if (!res.allowed) {
      reply.header("Retry-After", String(Math.max(1, res.resetAfterSec)));
      return reply.code(429).send({
        error: "monthly_feature_quota_exceeded",
        feature: featureKey,
        reset_after_seconds: res.resetAfterSec,
      });
    }
  };
}
