func VerifyDynamicHMAC(
	initialKeys map[string][]byte,
	refreshCooldown time.Duration,
	nowFn func() time.Time,
	fetchKeys KeyFetcher,
	next http.Handler,
) http.Handler {
	var (
		mu          sync.RWMutex
		keys        = initialKeys
		lastRefresh time.Time
	)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		kid := strings.TrimSpace(r.Header.Get("X-Key-ID"))
		sigHex := strings.TrimSpace(r.Header.Get("X-Payload-HMAC"))
		if kid == "" || sigHex == "" {
			http.Error(w, "missing key id or hmac", http.StatusUnauthorized)
			return
		}
		gotMAC, err := hex.DecodeString(sigHex)
		if err != nil || len(gotMAC) != sha256.Size {
			http.Error(w, "malformed hmac", http.StatusUnauthorized)
			return
		}

		mu.RLock()
		secret, found := keys[kid]
		mu.RUnlock()

		if !found {
			mu.Lock()
			secret, found = keys[kid]
			now := nowFn()
			if !found && (lastRefresh.IsZero() || now.Sub(lastRefresh) >= refreshCooldown) {
				lastRefresh = now
				fctx, cancel := context.WithTimeout(r.Context(), time.Second)
				freshMap, ferr := fetchKeys(fctx)
				cancel()
				if ferr == nil && freshMap != nil {
					keys = freshMap
					secret, found = keys[kid]
				}
			}
			mu.Unlock()
		}

		if !found || len(secret) == 0 {
			http.Error(w, "unknown key id", http.StatusUnauthorized)
			return
		}

		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 512<<10))
		if err != nil {
			http.Error(w, "invalid body", http.StatusBadRequest)
			return
		}

		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(kid + ":"))
		mac.Write(body)
		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
			http.Error(w, "hmac mismatch", http.StatusUnauthorized)
			return
		}

		r.Body = io.NopCloser(bytes.NewReader(body))
		next.ServeHTTP(w, r)
	})
}
