_REFANG_SCHEME_RE = re.compile(r"\bhxxp(s?)\s*(?:\[:\]|:)//", re.IGNORECASE)


def _refang_text(text: str) -> str:
    step1 = _REFANG_SCHEME_RE.sub(lambda m: f"http{m.group(1).lower()}://", text)
    return step1.replace("[.]", ".").replace("[:]/", ":/")


def extract_normalized_mime_urls(raw_email: bytes) -> list[str]:
    msg = BytesParser(policy=policy.default).parsebytes(raw_email)
    found: set[str] = set()

    for part in msg.walk():
        if part.is_multipart() or part.get_content_disposition() == "attachment":
            continue
        if part.get_content_type() not in ("text/plain", "text/html"):
            continue

        raw_bytes = part.get_payload(decode=True)
        if not raw_bytes:
            continue
        charset = part.get_content_charset() or "utf-8"
        try:
            decoded = raw_bytes.decode(charset, errors="replace")
        except LookupError:
            decoded = raw_bytes.decode("utf-8", errors="replace")

        refanged = _refang_text(decoded)
        for match in _URL_RE.findall(refanged):
            cleaned = match.rstrip(".,;)>\"'")
            if cleaned.lower().startswith(("http://", "https://")):
                found.add(cleaned)

    return sorted(found)
