```ts
export function signedSessionCookie(
  cookieSecret: Buffer,
  nowSecFn = () => Math.floor(Date.now() / 1000),
): MiddlewareHandler<Env> {
  if (cookieSecret.length < 32) {
    throw new Error("cookieSecret must be at least 32 bytes");
  }

  return async (c, next) => {
    const raw = getCookie(c, "__Host-sess");
    if (!raw) {
      return c.json({ error: "missing_session_cookie" }, 401);
    }

    const parts = raw.split(".");
    if (parts.length !== 2 || !parts[0] || !parts[1]) {
      return c.json({ error: "malformed_session_cookie" }, 401);
    }

    const [payloadB64, sigB64] = parts;
    const gotSig = Buffer.from(sigB64, "base64url");
    const expectedSig = createHmac("sha256", cookieSecret).update(payloadB64, "ascii").digest();
    if (gotSig.length !== expectedSig.length || !timingSafeEqual(gotSig, expectedSig)) {
      return c.json({ error: "invalid_session_signature" }, 401);
    }

    let session: SessionData;
    try {
      session = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf8")) as SessionData;
    } catch {
      return c.json({ error: "corrupt_session_payload" }, 401);
    }

    if (
      !session ||
      typeof session.uid !== "string" ||
      typeof session.role !== "string" ||
      typeof session.uaHash !== "string" ||
      typeof session.exp !== "number" ||
      session.exp <= nowSecFn()
    ) {
      return c.json({ error: "expired_or_invalid_session" }, 401);
    }

    const currentUaHash = createHash("sha256")
      .update(c.req.header("User-Agent") ?? "", "utf8")
      .digest("hex");
    const a = Buffer.from(session.uaHash, "utf8");
    const b = Buffer.from(currentUaHash, "utf8");
    if (a.length !== b.length || !timingSafeEqual(a, b)) {
      return c.json({ error: "session_user_agent_mismatch" }, 401);
    }

    c.set("session", session);
    await next();
  };
}
```

