```c
static inline uint32_t le32_load(const uint8_t *p) {
    return (uint32_t)p[0]
         | ((uint32_t)p[1] << 8)
         | ((uint32_t)p[2] << 16)
         | ((uint32_t)p[3] << 24);
}

[[nodiscard]] bool parse_radiotap_80211(const uint8_t *frame, size_t frame_len, radiotap_view_t *out) {
    if (frame == nullptr || out == nullptr || frame_len < 8u) {
        return false;
    }
    if (frame[0] != 0u) {
        return false; // it_version must be 0
    }

    size_t it_len = (size_t)frame[2] | ((size_t)frame[3] << 8);
    if (it_len < 8u || it_len > frame_len) {
        return false;
    }

    size_t pos = 4u;
    size_t words = 0u;
    while (true) {
        size_t word_end = 0;
        if (ckd_add(&word_end, pos, (size_t)4u) || word_end > it_len) {
            return false;
        }
        uint32_t bitmap = le32_load(frame + pos);
        words += 1u;
        pos = word_end;
        if ((bitmap & 0x80000000u) == 0u) {
            break;
        }
    }

    out->radiotap_len = it_len;
    out->present_words = words;
    out->dot11_mac = frame + it_len;
    out->dot11_len = frame_len - it_len;
    return true;
}
