```rust
fn derive_enc_and_commit(master_key: &[u8; 32], nonce: &[u8; 12]) -> ([u8; 32], [u8; 32]) {
    let mut h_enc = Sha256::new();
    h_enc.update(b"kc-gcm-enc-v1\x01");
    h_enc.update(master_key);
    h_enc.update(nonce);
    let k_enc: [u8; 32] = h_enc.finalize().into();

    let mut h_com = Sha256::new();
    h_com.update(b"kc-gcm-com-v1\x02");
    h_com.update(master_key);
    h_com.update(nonce);
    let k_commit: [u8; 32] = h_com.finalize().into();

    (k_enc, k_commit)
}

fn ct_eq_32(a: &[u8; 32], b: &[u8]) -> bool {
    if b.len() != 32 {
        return false;
    }
    let mut diff = 0u8;
    for i in 0..32 {
        diff |= core::hint::black_box(a[i] ^ b[i]);
    }
    core::hint::black_box(diff) == 0
}

pub fn seal_committing(
    master_key: &[u8; 32],
    aad: &[u8],
    plaintext: &[u8],
) -> Result<Vec<u8>, CommitAeadError> {
    let nonce = Aes256Gcm::generate_nonce(&mut OsRng);
    let mut nonce_arr = [0u8; 12];
    nonce_arr.copy_from_slice(nonce.as_slice());

    let (k_enc, k_commit) = derive_enc_and_commit(master_key, &nonce_arr);
    let mut bound_aad = Vec::with_capacity(32 + aad.len());
    bound_aad.extend_from_slice(&k_commit);
    bound_aad.extend_from_slice(aad);

    let cipher = Aes256Gcm::new_from_slice(&k_enc).map_err(|_| CommitAeadError::KeyCommitmentOrTagFailed)?;
    let ct = cipher
        .encrypt(&nonce, Payload { msg: plaintext, aad: &bound_aad })
        .map_err(|_| CommitAeadError::KeyCommitmentOrTagFailed)?;

    let mut out = Vec::with_capacity(12 + 32 + ct.len());
    out.extend_from_slice(&nonce_arr);
    out.extend_from_slice(&k_commit);
    out.extend_from_slice(&ct);
    Ok(out)
}

pub fn open_committing(
    master_key: &[u8; 32],
    aad: &[u8],
    blob: &[u8],
) -> Result<Vec<u8>, CommitAeadError> {
    if blob.len() < 12 + 32 + 16 {
        return Err(CommitAeadError::Truncated);
    }
    let mut nonce_arr = [0u8; 12];
    nonce_arr.copy_from_slice(&blob[0..12]);
    let wire_commit = &blob[12..44];
    let ct = &blob[44..];

    let (k_enc, expected_commit) = derive_enc_and_commit(master_key, &nonce_arr);
    if !ct_eq_32(&expected_commit, wire_commit) {
        return Err(CommitAeadError::KeyCommitmentOrTagFailed);
    }

    let mut bound_aad = Vec::with_capacity(32 + aad.len());
    bound_aad.extend_from_slice(&expected_commit);
    bound_aad.extend_from_slice(aad);

    let cipher = Aes256Gcm::new_from_slice(&k_enc).map_err(|_| CommitAeadError::KeyCommitmentOrTagFailed)?;
    cipher
        .decrypt(Nonce::from_slice(&nonce_arr), Payload { msg: ct, aad: &bound_aad })
        .map_err(|_| CommitAeadError::KeyCommitmentOrTagFailed)
}
